__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters1",{enumerable:!0,get:function(){return t}});const t={"chapter:titans-and-old-gods":{title:"\u0422\u0438\u0442\u0430\u043d\u044b \u0438 \u0414\u0440\u0435\u0432\u043d\u0438\u0435 \u0431\u043e\u0433\u0438",summary:"\u0417\u0430\u0434\u043e\u043b\u0433\u043e \u0434\u043e \u043f\u0435\u0440\u0432\u044b\u0445 \u0441\u043c\u0435\u0440\u0442\u043d\u044b\u0445 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432 \u0442\u0438\u0442\u0430\u043d\u044b \u041f\u0430\u043d\u0442\u0435\u043e\u043d\u0430 \u0441\u0440\u0430\u0436\u0430\u043b\u0438\u0441\u044c \u0441 \u0414\u0440\u0435\u0432\u043d\u0438\u043c\u0438 \u0431\u043e\u0433\u0430\u043c\u0438 \u0437\u0430 \u0434\u0443\u0448\u0443 \u044e\u043d\u043e\u0433\u043e \u043c\u0438\u0440\u0430, \u0438 \u0410\u0437\u0435\u0440\u043e\u0442 \u0434\u043e \u0441\u0438\u0445 \u043f\u043e\u0440 \u043d\u043e\u0441\u0438\u0442 \u0448\u0440\u0430\u043c\u044b \u0442\u043e\u0439 \u0432\u043e\u0439\u043d\u044b.",when:"\u0414\u043e \u043d\u0430\u0447\u0430\u043b\u0430 \u043f\u0438\u0441\u044c\u043c\u0435\u043d\u043d\u043e\u0439 \u0438\u0441\u0442\u043e\u0440\u0438\u0438",body:["\u0417\u0430\u0434\u043e\u043b\u0433\u043e \u0434\u043e \u0442\u043e\u0433\u043e, \u043a\u0430\u043a \u0441\u043c\u0435\u0440\u0442\u043d\u044b\u0435 \u043d\u0430\u0447\u0430\u043b\u0438 \u0432\u0435\u0441\u0442\u0438 \u043b\u0435\u0442\u043e\u043f\u0438\u0441\u0438, \u0442\u0438\u0442\u0430\u043d\u044b \u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 \u043f\u043e \u0431\u0435\u0441\u043a\u0440\u0430\u0439\u043d\u0435\u0439 \u0442\u044c\u043c\u0435 \u043a\u043e\u0441\u043c\u043e\u0441\u0430: \u0434\u0443\u0448\u0438 \u043c\u0438\u0440\u043e\u0432, \u0432\u044b\u0440\u043e\u0441\u0448\u0438\u0435 \u0432 \u0436\u0438\u0432\u044b\u0445 \u0432\u0435\u043b\u0438\u043a\u0430\u043d\u043e\u0432. \u0411\u043b\u0430\u0433\u043e\u0440\u043e\u0434\u043d\u0435\u0439\u0448\u0438\u0435 \u0438\u0437 \u043d\u0438\u0445 \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0438\u043b\u0438\u0441\u044c \u0432 \u041f\u0430\u043d\u0442\u0435\u043e\u043d \u0438 \u0438\u0441\u043a\u0430\u043b\u0438 \u0441\u0440\u0435\u0434\u0438 \u0437\u0432\u0435\u0437\u0434 \u0441\u043f\u044f\u0449\u0438\u0435 \u0434\u0443\u0448\u0438 \u043c\u0438\u0440\u043e\u0432, \u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0435 \u0438\u043c \u0441\u0430\u043c\u0438\u043c. \u0413\u043b\u0443\u0431\u043e\u043a\u043e \u0432 \u0410\u0437\u0435\u0440\u043e\u0442\u0435 \u043e\u043d\u0438 \u043e\u0449\u0443\u0442\u0438\u043b\u0438 \u0434\u0443\u0448\u0443 \u043d\u0435\u0432\u0438\u0434\u0430\u043d\u043d\u043e\u0439 \u0441\u0438\u043b\u044b, \u043d\u043e \u0442\u0435\u043c\u043d\u044b\u0435 \u0441\u0438\u043b\u044b \u043d\u0430\u0448\u043b\u0438 \u0435\u0435 \u043f\u0435\u0440\u0432\u044b\u043c\u0438.","\u041f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u0438 \u0411\u0435\u0437\u0434\u043d\u044b \u043d\u0438\u0437\u0432\u0435\u0440\u0433\u043b\u0438 \u043d\u0430 \u044e\u043d\u044b\u0439 \u043c\u0438\u0440 \u0441\u0432\u043e\u0438\u0445 \u0441\u043b\u0443\u0433, \u0414\u0440\u0435\u0432\u043d\u0438\u0445 \u0431\u043e\u0433\u043e\u0432. \u0418'\u0428\u0430\u0440\u0430\u0434\u0436, \u041a'\u0422\u0443\u043d, \u0419\u043e\u0433\u0433-\u0421\u0430\u0440\u043e\u043d \u0438 \u041d'\u0417\u043e\u0442 \u0432\u0440\u043e\u0441\u043b\u0438 \u0442\u0435\u043b\u0430\u043c\u0438 \u0432 \u0437\u0435\u043c\u043d\u0443\u044e \u043a\u043e\u0440\u0443 \u0438 \u0432\u043e\u0437\u0434\u0432\u0438\u0433\u043b\u0438 \u0427\u0435\u0440\u043d\u0443\u044e \u0438\u043c\u043f\u0435\u0440\u0438\u044e, \u0430 \u0435\u0435 \u043f\u043e\u043b\u043a\u043e\u0432\u043e\u0434\u0446\u0430\u043c\u0438 \u0441\u0442\u0430\u043b\u0438 \u043f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u0438 \u0441\u0442\u0438\u0445\u0438\u0439 \u043e\u0433\u043d\u044f, \u0437\u0435\u043c\u043b\u0438, \u0432\u043e\u0437\u0434\u0443\u0445\u0430 \u0438 \u0432\u043e\u0434\u044b. \u041a\u043e\u0433\u0434\u0430 \u043f\u0440\u0438\u0448\u0435\u043b \u041f\u0430\u043d\u0442\u0435\u043e\u043d, \u0435\u0433\u043e \u0430\u0440\u043c\u0438\u0438, \u0441\u043e\u0437\u0434\u0430\u043d\u043d\u044b\u0435 \u0442\u0438\u0442\u0430\u043d\u0430\u043c\u0438, \u0441\u043e\u043a\u0440\u0443\u0448\u0438\u043b\u0438 \u0446\u0438\u0442\u0430\u0434\u0435\u043b\u0438 \u0438\u043c\u043f\u0435\u0440\u0438\u0438. \u0412\u0435\u0440\u0445\u043e\u0432\u043d\u044b\u0439 \u043e\u0442\u0435\u0446 \u0410\u043c\u0430\u043d'\u0422\u0443\u043b \u0432\u044b\u0440\u0432\u0430\u043b \u0418'\u0428\u0430\u0440\u0430\u0434\u0436\u0430 \u0438\u0437 \u0437\u0435\u043c\u043b\u0438, \u043d\u043e \u0443\u0434\u0430\u0440 \u043e\u0442\u043a\u0440\u044b\u043b \u0440\u0430\u043d\u0443, \u0438\u0437 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0445\u043b\u044b\u043d\u0443\u043b\u0430 \u0442\u0430\u0439\u043d\u0430\u044f \u0436\u0438\u0437\u043d\u0435\u043d\u043d\u0430\u044f \u0441\u0438\u043b\u0430 \u043c\u0438\u0440\u0430. \u0422\u0438\u0442\u0430\u043d\u044b \u043f\u043e\u043d\u044f\u043b\u0438, \u0447\u0442\u043e, \u0443\u0431\u0438\u0432 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445, \u043c\u043e\u0433\u0443\u0442 \u043f\u043e\u0433\u0443\u0431\u0438\u0442\u044c \u0438 \u0441\u0430\u043c \u0410\u0437\u0435\u0440\u043e\u0442.","\u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u0445\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u0438 \u0432\u044b\u0431\u0440\u0430\u043b\u0438 \u0442\u0435\u043c\u043d\u0438\u0446\u044b. \u041a'\u0422\u0443\u043d\u0430, \u0419\u043e\u0433\u0433-\u0421\u0430\u0440\u043e\u043d\u0430 \u0438 \u041d'\u0417\u043e\u0442\u0430 \u0437\u0430\u043a\u043e\u0432\u0430\u043b\u0438 \u0433\u043b\u0443\u0431\u043e\u043a\u043e \u043f\u043e\u0434 \u0437\u0435\u043c\u043b\u0435\u0439, \u0430 \u043f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u0435\u0439 \u0441\u0442\u0438\u0445\u0438\u0439 \u0438\u0437\u0433\u043d\u0430\u043b\u0438 \u043d\u0430 \u041f\u043b\u0430\u043d \u0441\u0442\u0438\u0445\u0438\u0439, \u0432 \u0447\u044c\u0438 \u043f\u0440\u0435\u0434\u0435\u043b\u044b \u0432\u0445\u043e\u0434\u044f\u0442 Skywall \u0438 \u041e\u0433\u043d\u0435\u043d\u043d\u044b\u0435 \u041f\u0440\u043e\u0441\u0442\u043e\u0440\u044b. \u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u0438 \u0443\u0441\u043c\u0438\u0440\u0438\u043b\u0438 \u043a\u0440\u043e\u0432\u043e\u0442\u043e\u0447\u0430\u0449\u0443\u044e \u0440\u0430\u043d\u0443, \u043f\u0440\u0435\u0432\u0440\u0430\u0442\u0438\u0432 \u0435\u0435 \u0432 \u0441\u0438\u044f\u044e\u0449\u0435\u0435 \u043e\u0437\u0435\u0440\u043e, \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0412\u0435\u0447\u043d\u043e\u0441\u0442\u0438, \u0441\u043e\u0442\u0432\u043e\u0440\u0438\u043b\u0438 \u0433\u043e\u0440\u044b \u0438 \u043c\u043e\u0440\u044f \u0438 \u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0438 \u043f\u043e\u0441\u043b\u0435 \u0441\u0435\u0431\u044f \u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0430 \u0442\u0438\u0442\u0430\u043d\u043e\u0432, \u0442\u0430\u043a\u0438\u0435 \u043a\u0430\u043a \u0423\u043b\u044c\u0434\u0430\u043c\u0430\u043d. \u041a\u043e\u0433\u0434\u0430 \u043f\u0430\u043b \u0447\u0443\u0434\u043e\u0432\u0438\u0449\u043d\u044b\u0439 \u043f\u0440\u043e\u0442\u043e\u0434\u0440\u0430\u043a\u043e\u043d \u0413\u0430\u043b\u0430\u043a\u0440\u043e\u043d\u0434, \u041f\u0430\u043d\u0442\u0435\u043e\u043d \u043d\u0430\u0434\u0435\u043b\u0438\u043b \u043f\u044f\u0442\u0435\u0440\u044b\u0445 \u0432\u0435\u043b\u0438\u043a\u0438\u0445 \u0434\u0440\u0430\u043a\u043e\u043d\u043e\u0432 \u0441\u0438\u043b\u043e\u0439 \u0410\u0441\u043f\u0435\u043a\u0442\u043e\u0432, \u0447\u0442\u043e\u0431\u044b \u0442\u0435 \u043e\u0445\u0440\u0430\u043d\u044f\u043b\u0438 \u043c\u0438\u0440, \u0430 \u0437\u0430\u0442\u0435\u043c \u0443\u0434\u0430\u043b\u0438\u043b\u0441\u044f \u043a \u0437\u0432\u0435\u0437\u0434\u0430\u043c."]},"chapter:sargeras-and-the-burning-legion":{title:"\u0421\u0430\u0440\u0433\u0435\u0440\u0430\u0441 \u0438 \u041f\u044b\u043b\u0430\u044e\u0449\u0438\u0439 \u041b\u0435\u0433\u0438\u043e\u043d",summary:"\u0412\u0435\u043b\u0438\u0447\u0430\u0439\u0448\u0438\u0439 \u0437\u0430\u0449\u0438\u0442\u043d\u0438\u043a \u041f\u0430\u043d\u0442\u0435\u043e\u043d\u0430 \u0443\u0442\u0440\u0430\u0442\u0438\u043b \u0432\u0435\u0440\u0443 \u0432 \u043c\u0438\u0440\u043e\u0437\u0434\u0430\u043d\u0438\u0435 \u0438 \u043d\u0430\u0447\u0430\u043b \u0434\u0435\u043c\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u0440\u0435\u0441\u0442\u043e\u0432\u044b\u0439 \u043f\u043e\u0445\u043e\u0434, \u0447\u0442\u043e\u0431\u044b \u0441\u0436\u0435\u0447\u044c \u0435\u0433\u043e, \u0430 \u0410\u0437\u0435\u0440\u043e\u0442 \u0441\u0442\u0430\u043b \u0434\u043e\u0431\u044b\u0447\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043e\u043d \u0436\u0430\u0436\u0434\u0430\u043b \u0431\u043e\u043b\u044c\u0448\u0435 \u0432\u0441\u0435\u0433\u043e.",when:"\u0417\u0430\u0434\u043e\u043b\u0433\u043e \u0434\u043e \u043d\u043e\u0447\u043d\u044b\u0445 \u044d\u043b\u044c\u0444\u043e\u0432",body:["\u0421\u0430\u0440\u0433\u0435\u0440\u0430\u0441 \u0431\u044b\u043b \u0437\u0430\u0449\u0438\u0442\u043d\u0438\u043a\u043e\u043c \u041f\u0430\u043d\u0442\u0435\u043e\u043d\u0430, \u0442\u0438\u0442\u0430\u043d\u043e\u043c, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u0445\u043e\u0442\u0438\u043b\u0441\u044f \u043d\u0430 \u0434\u0435\u043c\u043e\u043d\u043e\u0432 \u043f\u043e \u0432\u0441\u0435\u043c\u0443 \u043a\u043e\u0441\u043c\u043e\u0441\u0443 \u0438 \u0437\u0430\u0442\u043e\u0447\u0430\u043b \u0438\u0445 \u0432 \u043c\u0438\u0440\u0435-\u0442\u0435\u043c\u043d\u0438\u0446\u0435 \u043f\u043e\u0434 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435\u043c \u041c\u0430\u0440\u0434\u0443\u043c. \u0417\u0430 \u044d\u043f\u043e\u0445\u0438 \u0432\u043e\u0439\u043d \u043e\u043d \u0443\u0437\u043d\u0430\u043b, \u0447\u0435\u0433\u043e \u043d\u0430 \u0441\u0430\u043c\u043e\u043c \u0434\u0435\u043b\u0435 \u0445\u043e\u0442\u044f\u0442 \u041f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u0438 \u0411\u0435\u0437\u0434\u043d\u044b: \u043e\u0441\u043a\u0432\u0435\u0440\u043d\u0438\u0442\u044c \u0434\u0443\u0448\u0443 \u043c\u0438\u0440\u0430 \u0438 \u043f\u043e\u0440\u043e\u0434\u0438\u0442\u044c \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0442\u0435\u043c\u043d\u043e\u0433\u043e \u0442\u0438\u0442\u0430\u043d\u0430. \u0423\u0432\u0435\u0440\u0438\u0432\u0448\u0438\u0441\u044c, \u0447\u0442\u043e \u043c\u0438\u0440\u043e\u0437\u0434\u0430\u043d\u0438\u0435 \u043f\u043e\u0440\u043e\u0447\u043d\u043e \u0438 \u0441\u043f\u0430\u0441\u0442\u0438 \u0435\u0433\u043e \u043d\u0435\u043b\u044c\u0437\u044f, \u043e\u043d \u0440\u0435\u0448\u0438\u043b, \u0447\u0442\u043e \u043c\u0438\u043b\u043e\u0441\u0435\u0440\u0434\u043d\u0435\u0435 \u0431\u0443\u0434\u0435\u0442 \u0441\u0436\u0435\u0447\u044c \u0432\u0441\u0435.","\u041e\u043d \u0440\u0430\u0437\u0440\u0443\u0448\u0438\u043b \u0442\u0435\u043c\u043d\u0438\u0446\u0443 \u041c\u0430\u0440\u0434\u0443\u043c\u0430 \u0438 \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u043b \u0435\u0435 \u0434\u0435\u043c\u043e\u043d\u043e\u0432, \u0441\u0442\u0430\u0432\u0448\u0438\u0445 \u043f\u0435\u0440\u0432\u044b\u043c\u0438 \u0440\u044f\u0434\u0430\u043c\u0438 \u041f\u044b\u043b\u0430\u044e\u0449\u0435\u0433\u043e \u041b\u0435\u0433\u0438\u043e\u043d\u0430. \u0412 \u043c\u0438\u0440\u0435 \u0410\u0440\u0433\u0443\u0441 \u043e\u043d \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u043b \u044d\u0440\u0435\u0434\u0430\u0440\u0430\u043c \u0437\u043d\u0430\u043d\u0438\u044f \u0438 \u0441\u0438\u043b\u0443; \u0438\u0445 \u0432\u043e\u0436\u0434\u0438 \u041a\u0438\u043b'\u0434\u0436\u0435\u0434\u0435\u043d \u0438 \u0410\u0440\u0445\u0438\u043c\u043e\u043d\u0434 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u043b\u0438\u0441\u044c, \u0430 \u043f\u0440\u043e\u0440\u043e\u043a \u0412\u0435\u043b\u0435\u043d \u0431\u0435\u0436\u0430\u043b \u0441 \u0442\u0435\u043c\u0438, \u043a\u0442\u043e \u043e\u0442\u043a\u0430\u0437\u0430\u043b\u0441\u044f, \u2014 \u0441 \u043d\u0430\u0440\u043e\u0434\u043e\u043c, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043f\u043e\u0437\u0434\u043d\u0435\u0435 \u043d\u0430\u0437\u043e\u0432\u0443\u0442 \u0434\u0440\u0435\u043d\u0435\u044f\u043c\u0438. \u041f\u0430\u043d\u0442\u0435\u043e\u043d \u043f\u043e\u043f\u044b\u0442\u0430\u043b\u0441\u044f \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0441\u0432\u043e\u0435\u0433\u043e \u0431\u044b\u043b\u043e\u0433\u043e \u0437\u0430\u0449\u0438\u0442\u043d\u0438\u043a\u0430 \u0438 \u043f\u0430\u043b \u043e\u0442 \u0435\u0433\u043e \u0440\u0443\u043a\u0438.","\u0421 \u0442\u0435\u0445 \u043f\u043e\u0440 \u041b\u0435\u0433\u0438\u043e\u043d \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0438\u043b \u0438\u0437 \u043c\u0438\u0440\u0430 \u0432 \u043c\u0438\u0440 \u043f\u043e\u0434 \u043d\u0430\u0447\u0430\u043b\u043e\u043c \u0421\u0430\u0440\u0433\u0435\u0440\u0430\u0441\u0430; \u0435\u043c\u0443 \u0441\u043b\u0443\u0436\u0438\u043b\u0438 \u044d\u0440\u0435\u0434\u0430\u0440\u044b, \u043f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u0438 \u0443\u0436\u0430\u0441\u0430, \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u043c\u044b\u0435 \u043d\u0430\u0442\u0440\u0435\u0437\u0438\u043c\u0430\u043c\u0438, \u0438 \u0431\u0435\u0441\u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0435 \u0434\u0435\u043c\u043e\u043d\u044b \u043f\u043e\u043c\u0435\u043d\u044c\u0448\u0435. \u0410\u0437\u0435\u0440\u043e\u0442 \u0437\u043d\u0430\u0447\u0438\u043b \u0434\u043b\u044f \u043d\u0435\u0433\u043e \u0431\u043e\u043b\u044c\u0448\u0435 \u043c\u043d\u043e\u0433\u0438\u0445 \u043c\u0438\u0440\u043e\u0432: \u0434\u0443\u0448\u0430 \u043c\u0438\u0440\u0430, \u0432\u0441\u0435 \u0435\u0449\u0435 \u0441\u043f\u044f\u0449\u0430\u044f \u0438 \u0443\u0436\u0435 \u043e\u0442\u043c\u0435\u0447\u0435\u043d\u043d\u0430\u044f \u0414\u0440\u0435\u0432\u043d\u0438\u043c\u0438 \u0431\u043e\u0433\u0430\u043c\u0438. \u041a\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 World of Warcraft \u041b\u0435\u0433\u0438\u043e\u043d \u0434\u0432\u0430\u0436\u0434\u044b \u0432\u0442\u043e\u0440\u0433\u0430\u043b\u0441\u044f \u0432 \u043d\u0435\u0433\u043e, \u0430 \u0435\u0433\u043e \u0448\u0435\u043f\u043e\u0442 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u043b \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u044d\u043b\u044c\u0444\u043e\u0432, \u043e\u0440\u043a\u043e\u0432 \u0438 \u043b\u044e\u0434\u0435\u0439."]},"chapter:rise-of-the-kaldorei":{title:"\u0412\u043e\u0437\u0432\u044b\u0448\u0435\u043d\u0438\u0435 \u043a\u0430\u043b\u0434\u043e\u0440\u0430\u0439",summary:"\u0422\u0440\u043e\u043b\u043b\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0438 \u0434\u0440\u0435\u0432\u043d\u0438\u043c \u041a\u0430\u043b\u0438\u043c\u0434\u043e\u0440\u043e\u043c, \u043f\u043e\u043a\u0430 \u043f\u043b\u0435\u043c\u044f, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0442\u044f\u043d\u0443\u043b\u043e\u0441\u044c \u043a \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0443 \u0412\u0435\u0447\u043d\u043e\u0441\u0442\u0438, \u043d\u0435 \u0441\u0442\u0430\u043b\u043e \u043d\u043e\u0447\u043d\u044b\u043c\u0438 \u044d\u043b\u044c\u0444\u0430\u043c\u0438, \u0447\u044c\u044f \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430 \u0410\u0437\u0448\u0430\u0440\u0430 \u0432\u044b\u0441\u0442\u0440\u043e\u0438\u043b\u0430 \u0438\u043c\u043f\u0435\u0440\u0438\u044e \u043f\u043e\u0440\u0430\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043c\u0430\u0433\u0438\u0438.",when:"\u041f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0437\u0430 15 000\u201310 000 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u0412 \u044d\u043f\u043e\u0445\u0438 \u043f\u043e\u0441\u043b\u0435 \u0443\u0445\u043e\u0434\u0430 \u0442\u0438\u0442\u0430\u043d\u043e\u0432 \u041a\u0430\u043b\u0438\u043c\u0434\u043e\u0440 \u0431\u044b\u043b \u0435\u0434\u0438\u043d\u044b\u043c \u043e\u0433\u0440\u043e\u043c\u043d\u044b\u043c \u043c\u0430\u0442\u0435\u0440\u0438\u043a\u043e\u043c. \u0422\u0440\u043e\u043b\u043b\u0438 \u0432\u043e \u0433\u043b\u0430\u0432\u0435 \u0441 \u0437\u0430\u043d\u0434\u0430\u043b\u0430\u0440\u0430\u043c\u0438 \u0434\u043e\u043b\u0433\u043e \u0432\u043e\u0435\u0432\u0430\u043b\u0438 \u0441 \u043d\u0430\u0441\u0435\u043a\u043e\u043c\u043e\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u043c\u0438 \u0430\u043a\u0438\u0440\u0430\u043c\u0438, \u043e\u0441\u0442\u0430\u0442\u043a\u0430\u043c\u0438 \u0441\u043b\u0443\u0433 \u0414\u0440\u0435\u0432\u043d\u0438\u0445 \u0431\u043e\u0433\u043e\u0432, \u0438 \u043e\u0442\u0442\u0435\u0441\u043d\u0438\u043b\u0438 \u0438\u0445 \u043d\u0430 \u043a\u0440\u0430\u0439\u043d\u0438\u0439 \u0441\u0435\u0432\u0435\u0440 \u0438 \u044e\u0433, \u0433\u0434\u0435 \u0438\u0445 \u043f\u043e\u0442\u043e\u043c\u043a\u0438 \u043f\u043e\u0437\u0436\u0435 \u0441\u0442\u0430\u043d\u0443\u0442 \u043d\u0435\u0440\u0443\u0431\u0430\u043c\u0438 \u0438 \u043a\u0438\u0440\u0430\u0436\u0430\u043c\u0438. \u041f\u043e\u0441\u043b\u0435 \u043f\u043e\u0431\u0435\u0434\u044b \u0442\u0440\u043e\u043b\u043b\u0438 \u0440\u0430\u0437\u0434\u0435\u043b\u0438\u043b\u0438\u0441\u044c \u043d\u0430 \u0441\u043e\u043f\u0435\u0440\u043d\u0438\u0447\u0430\u044e\u0449\u0438\u0435 \u0438\u043c\u043f\u0435\u0440\u0438\u0438, \u0442\u0430\u043a\u0438\u0435 \u043a\u0430\u043a \u0413\u0443\u0440\u0443\u0431\u0430\u0448\u0438 \u0438 \u0410\u043c\u0430\u043d\u0438.","\u041e\u0434\u043d\u043e \u043f\u043b\u0435\u043c\u044f \u0442\u0440\u043e\u043b\u043b\u0435\u0439 \u0438\u0437\u0431\u0440\u0430\u043b\u043e \u0431\u043e\u043b\u0435\u0435 \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u044b\u0439 \u043f\u0443\u0442\u044c. \u041e\u043d\u043e \u043f\u043e\u0441\u0435\u043b\u0438\u043b\u043e\u0441\u044c \u043d\u0430 \u0431\u0435\u0440\u0435\u0433\u0430\u0445 \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0412\u0435\u0447\u043d\u043e\u0441\u0442\u0438, \u0438 \u0437\u0430 \u043c\u043d\u043e\u0433\u043e \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u0439 \u0435\u0433\u043e \u0441\u0438\u043b\u0430 \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0430 \u044d\u0442\u043e\u0442 \u043d\u0430\u0440\u043e\u0434: \u043e\u043d \u0441\u0442\u0430\u043b \u0432\u044b\u0448\u0435 \u0438 \u0434\u043e\u043b\u0433\u043e\u0432\u0435\u0447\u043d\u0435\u0435, \u043d\u0430\u0447\u0430\u043b \u043f\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u043b\u0443\u043d\u043d\u0443\u044e \u0431\u043e\u0433\u0438\u043d\u044e \u042d\u043b\u0443\u043d\u0443 \u0438 \u043d\u0430\u0437\u0432\u0430\u043b \u0441\u0435\u0431\u044f \u043a\u0430\u043b\u0434\u043e\u0440\u0430\u0439, \xab\u0434\u0435\u0442\u0438 \u0437\u0432\u0435\u0437\u0434\xbb. \u041f\u043e\u0434 \u043f\u043e\u043a\u0440\u043e\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u043f\u043e\u043b\u0443\u0431\u043e\u0433\u0430 \u041a\u0435\u043d\u0430\u0440\u0438\u044f \u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u0434\u0440\u0435\u0432\u043d\u0438\u0445 \u0434\u0443\u0445\u043e\u0432 \u043f\u0440\u0438\u0440\u043e\u0434\u044b \u043e\u043d\u0438 \u0432\u0441\u043a\u043e\u0440\u0435 \u0437\u0430\u0442\u043c\u0438\u043b\u0438 \u0441\u0432\u043e\u0438\u0445 \u0440\u043e\u0434\u0438\u0447\u0435\u0439-\u0442\u0440\u043e\u043b\u043b\u0435\u0439.","\u0412\u0435\u043b\u0438\u0447\u0430\u0439\u0448\u0435\u0439 \u0438\u0445 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0438\u0446\u0435\u0439 \u0441\u0442\u0430\u043b\u0430 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430 \u0410\u0437\u0448\u0430\u0440\u0430, \u043e\u0431\u043e\u0436\u0430\u0435\u043c\u0430\u044f \u043d\u0430\u0440\u043e\u0434\u043e\u043c; \u0435\u0439 \u0441\u043b\u0443\u0436\u0438\u043b\u0438 \u0432\u044b\u0441\u043e\u043a\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u043d\u044b\u0435, \u0430\u0440\u0438\u0441\u0442\u043e\u043a\u0440\u0430\u0442\u0438\u044f \u0447\u0430\u0440\u043e\u0434\u0435\u0435\u0432, \u0447\u0435\u0440\u043f\u0430\u0432\u0448\u0438\u0445 \u0438\u0437 \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0432\u0441\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 \u0441\u0438\u043b\u044b. \u0415\u0435 \u0434\u0432\u043e\u0440\u0435\u0446 \u0432 \u0417\u0438\u043d-\u0410\u0437\u0448\u0430\u0440\u0438 \u0441\u0442\u043e\u044f\u043b \u043d\u0430 \u0435\u0433\u043e \u0431\u0435\u0440\u0435\u0433\u0443, \u0430 \u0435\u0435 \u0438\u043c\u043f\u0435\u0440\u0438\u044f \u0440\u0430\u0441\u043a\u0438\u043d\u0443\u043b\u0430\u0441\u044c \u043f\u043e \u0432\u0441\u0435\u043c\u0443 \u041a\u0430\u043b\u0438\u043c\u0434\u043e\u0440\u0443. \u041e\u0434\u043d\u0430\u043a\u043e \u0436\u0430\u0436\u0434\u0430 \u043c\u0430\u0433\u0438\u0438 \u0432\u044b\u0441\u043e\u043a\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u043d\u044b\u0445 \u043f\u043e\u0441\u044b\u043b\u0430\u043b\u0430 \u0432\u043e\u043b\u043d\u044b \u0434\u0430\u043b\u0435\u043a\u043e \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u044b \u043c\u0438\u0440\u0430, \u0438 \u043d\u0435\u0447\u0442\u043e \u043e\u0433\u0440\u043e\u043c\u043d\u043e\u0435 \u0432 \u041a\u0440\u0443\u0433\u043e\u0432\u0435\u0440\u0442\u0438 \u041f\u0443\u0441\u0442\u043e\u0442\u044b \u0438\u0445 \u043f\u043e\u0447\u0443\u0432\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u043e."]},"chapter:war-of-the-ancients":{title:"\u0412\u043e\u0439\u043d\u0430 \u0414\u0440\u0435\u0432\u043d\u0438\u0445",summary:"\u0410\u0437\u0448\u0430\u0440\u0430 \u043e\u0442\u043a\u0440\u044b\u043b\u0430 \u043f\u0443\u0442\u044c \u041f\u044b\u043b\u0430\u044e\u0449\u0435\u043c\u0443 \u041b\u0435\u0433\u0438\u043e\u043d\u0443, \u0438 \u043c\u0438\u0440 \u0435\u0434\u0432\u0430 \u043d\u0435 \u043f\u043e\u0433\u0438\u0431, \u043f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0412\u0435\u0447\u043d\u043e\u0441\u0442\u0438 \u0440\u0430\u0437\u043e\u0440\u0432\u0430\u043b \u0441\u0430\u043c \u0441\u0435\u0431\u044f.",when:"\u041e\u043a\u043e\u043b\u043e 10 000 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u0421\u0430\u0440\u0433\u0435\u0440\u0430\u0441 \u043d\u0430\u0448\u0435\u043f\u0442\u044b\u0432\u0430\u043b \u0410\u0437\u0448\u0430\u0440\u0435 \u0438 \u0435\u0435 \u0432\u044b\u0441\u043e\u043a\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u043d\u044b\u043c, \u043e\u0431\u0435\u0449\u0430\u044f \u043c\u0438\u0440, \u043f\u0435\u0440\u0435\u0434\u0435\u043b\u0430\u043d\u043d\u044b\u0439 \u043f\u043e \u0438\u0445 \u043e\u0431\u0440\u0430\u0437\u0443. \u041e\u043d\u0438 \u043f\u043e\u0432\u0435\u0440\u0438\u043b\u0438 \u0435\u043c\u0443 \u0438 \u0447\u0435\u0440\u0435\u0437 \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0412\u0435\u0447\u043d\u043e\u0441\u0442\u0438 \u043e\u0442\u043a\u0440\u044b\u043b\u0438 \u0432\u0440\u0430\u0442\u0430 \u0434\u043b\u044f \u041f\u044b\u043b\u0430\u044e\u0449\u0435\u0433\u043e \u041b\u0435\u0433\u0438\u043e\u043d\u0430. \u0414\u0435\u043c\u043e\u043d\u044b \u0432\u043e \u0433\u043b\u0430\u0432\u0435 \u0441 \u0410\u0440\u0445\u0438\u043c\u043e\u043d\u0434\u043e\u043c \u0438 \u041c\u0430\u043d\u043d\u043e\u0440\u043e\u0445\u043e\u043c \u0445\u043b\u044b\u043d\u0443\u043b\u0438 \u0432 \u041a\u0430\u043b\u0438\u043c\u0434\u043e\u0440 \u0438 \u043f\u0440\u0438\u043d\u044f\u043b\u0438\u0441\u044c \u0438\u0441\u0442\u0440\u0435\u0431\u043b\u044f\u0442\u044c \u0442\u0435\u0445 \u0441\u0430\u043c\u044b\u0445 \u043a\u0430\u043b\u0434\u043e\u0440\u0430\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u043c\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430.","\u0421\u043e\u043f\u0440\u043e\u0442\u0438\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u043f\u043b\u043e\u0442\u0438\u043b\u043e\u0441\u044c \u0432\u043e\u043a\u0440\u0443\u0433 \u043d\u0435\u043e\u0436\u0438\u0434\u0430\u043d\u043d\u044b\u0445 \u0432\u043e\u0436\u0434\u0435\u0439: \u041c\u0430\u043b\u0444\u0443\u0440\u0438\u043e\u043d\u0430 \u042f\u0440\u043e\u0441\u0442\u0438 \u0411\u0443\u0440\u0438, \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u043d\u043e\u0447\u043d\u043e\u0433\u043e \u044d\u043b\u044c\u0444\u0430, \u043f\u043e\u0441\u0442\u0438\u0433\u0448\u0435\u0433\u043e \u0434\u0440\u0443\u0438\u0434\u0438\u0437\u043c \u0443 \u041a\u0435\u043d\u0430\u0440\u0438\u044f; \u0435\u0433\u043e \u0431\u0440\u0430\u0442\u0430-\u0431\u043b\u0438\u0437\u043d\u0435\u0446\u0430 \u0418\u043b\u043b\u0438\u0434\u0430\u043d\u0430, \u043e\u0434\u0430\u0440\u0435\u043d\u043d\u043e\u0433\u043e \u0447\u0430\u0440\u043e\u0434\u0435\u044f; \u0438 \u0422\u0438\u0440\u0430\u043d\u0434\u044b \u0428\u0435\u043b\u0435\u0441\u0442 \u0412\u0435\u0442\u0440\u0430, \u0436\u0440\u0438\u0446\u044b \u042d\u043b\u0443\u043d\u044b. \u041d\u0430 \u0438\u0445 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u0441\u0440\u0430\u0436\u0430\u043b\u0438\u0441\u044c \u043f\u043e\u043b\u0443\u0431\u043e\u0433\u0438 \u043f\u0440\u0438\u0440\u043e\u0434\u044b \u0438 \u0431\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u043e \u0434\u0440\u0430\u043a\u043e\u043d\u044c\u0438\u0445 \u0441\u0442\u0430\u0439. \u0427\u0435\u0440\u043d\u044b\u0439 \u0410\u0441\u043f\u0435\u043a\u0442 \u041d\u0435\u043b\u0442\u0430\u0440\u0438\u043e\u043d \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u043b \u043e\u0440\u0443\u0436\u0438\u0435, \u0414\u0443\u0448\u0443 \u0414\u0440\u0430\u043a\u043e\u043d\u0430, \u043d\u043e \u043e\u0431\u0440\u0430\u0442\u0438\u043b \u0435\u0433\u043e \u043f\u0440\u043e\u0442\u0438\u0432 \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u043e\u0432; \u0437\u0430 \u044d\u0442\u043e \u043f\u0440\u0435\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0435\u0433\u043e \u043f\u0440\u043e\u0437\u043e\u0432\u0443\u0442 \u0421\u043c\u0435\u0440\u0442\u043e\u043a\u0440\u044b\u043b\u043e\u043c.","\u041a\u043e\u0433\u0434\u0430 \u0441\u0430\u043c \u0421\u0430\u0440\u0433\u0435\u0440\u0430\u0441 \u043f\u043e\u043f\u044b\u0442\u0430\u043b\u0441\u044f \u043f\u0440\u043e\u0439\u0442\u0438 \u0447\u0435\u0440\u0435\u0437 \u043f\u043e\u0440\u0442\u0430\u043b, \u041c\u0430\u043b\u0444\u0443\u0440\u0438\u043e\u043d \u0438 \u0435\u0433\u043e \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0438 \u0441\u043e\u0440\u0432\u0430\u043b\u0438 \u0437\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u0435 \u0432\u044b\u0441\u043e\u043a\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u043d\u044b\u0445. \u041d\u0435\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u044b\u0439 \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0441\u0445\u043b\u043e\u043f\u043d\u0443\u043b\u0441\u044f, \u0438 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043b \u0412\u0435\u043b\u0438\u043a\u0438\u0439 \u0420\u0430\u0441\u043a\u043e\u043b: \u043c\u043e\u0440\u0435 \u043f\u043e\u0433\u043b\u043e\u0442\u0438\u043b\u043e \u0417\u0438\u043d-\u0410\u0437\u0448\u0430\u0440\u0438, \u041a\u0430\u043b\u0438\u043c\u0434\u043e\u0440 \u0440\u0430\u0441\u043a\u043e\u043b\u043e\u043b\u0441\u044f, \u0430 \u043d\u0430 \u043c\u0435\u0441\u0442\u0435 \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0437\u0430\u043a\u0440\u0443\u0436\u0438\u043b\u0430\u0441\u044c \u0431\u0443\u0440\u044f, \u043f\u0440\u043e\u0437\u0432\u0430\u043d\u043d\u0430\u044f \u0412\u043e\u0434\u043e\u0432\u043e\u0440\u043e\u0442\u043e\u043c. \u0410\u0437\u0448\u0430\u0440\u0430 \u0438 \u0435\u0435 \u0434\u0432\u043e\u0440 \u0441\u043a\u0440\u044b\u043b\u0438\u0441\u044c \u043f\u043e\u0434 \u0432\u043e\u043b\u043d\u0430\u043c\u0438, \u0447\u0442\u043e\u0431\u044b \u043e\u0434\u043d\u0430\u0436\u0434\u044b \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u0432 \u043e\u0431\u043b\u0438\u043a\u0435 \u043d\u0430\u0433. \u0418\u0437 \u0435\u0434\u0438\u043d\u043e\u0433\u043e \u043c\u0430\u0442\u0435\u0440\u0438\u043a\u0430 \u0432\u043e\u0437\u043d\u0438\u043a\u043b\u0438 \u0437\u0435\u043c\u043b\u0438, \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0435 \u043d\u044b\u043d\u0435 \u043a\u0430\u043a \u041a\u0430\u043b\u0438\u043c\u0434\u043e\u0440, \u0412\u043e\u0441\u0442\u043e\u0447\u043d\u044b\u0435 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u0438 \u041d\u043e\u0440\u0434\u0441\u043a\u043e\u043b."]},"chapter:the-long-watch-of-hyjal":{title:"\u0414\u043e\u043b\u0433\u0430\u044f \u0441\u0442\u0440\u0430\u0436\u0430 \u0425\u0438\u0434\u0436\u0430\u043b\u0430",summary:"\u0423\u0446\u0435\u043b\u0435\u0432\u0448\u0438\u0435 \u0432\u044b\u0440\u0430\u0441\u0442\u0438\u043b\u0438 \u0414\u0440\u0435\u0432\u043e \u041c\u0438\u0440\u0430 \u043d\u0430\u0434 \u0432\u0442\u043e\u0440\u044b\u043c \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c, \u0437\u0430\u0442\u043e\u0447\u0438\u043b\u0438 \u0418\u043b\u043b\u0438\u0434\u0430\u043d\u0430 \u043f\u043e\u0434 \u0437\u0435\u043c\u043b\u0435\u0439 \u0438 \u0434\u0435\u0441\u044f\u0442\u044c \u0442\u044b\u0441\u044f\u0447 \u043b\u0435\u0442 \u043d\u0435\u0441\u043b\u0438 \u0441\u0442\u0440\u0430\u0436\u0443.",when:"\u041f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0441 10 000 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u041d\u043e\u0447\u043d\u044b\u0435 \u044d\u043b\u044c\u0444\u044b, \u043f\u0435\u0440\u0435\u0436\u0438\u0432\u0448\u0438\u0435 \u0420\u0430\u0441\u043a\u043e\u043b, \u0441\u043e\u0431\u0440\u0430\u043b\u0438\u0441\u044c \u043d\u0430 \u0433\u043e\u0440\u0435 \u0425\u0438\u0434\u0436\u0430\u043b. \u0422\u0430\u043c \u043e\u043d\u0438 \u0443\u0437\u043d\u0430\u043b\u0438, \u0447\u0442\u043e \u0418\u043b\u043b\u0438\u0434\u0430\u043d \u0443\u043d\u0435\u0441 \u0441 \u0441\u043e\u0431\u043e\u0439 \u0444\u0438\u0430\u043b\u044b \u0441 \u0432\u043e\u0434\u043e\u0439 \u0441\u0442\u0430\u0440\u043e\u0433\u043e \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0438 \u0432\u044b\u043b\u0438\u043b \u0447\u0430\u0441\u0442\u044c \u0435\u0435 \u0432 \u0433\u043e\u0440\u043d\u043e\u0435 \u043e\u0437\u0435\u0440\u043e, \u0441\u043e\u0437\u0434\u0430\u0432 \u043d\u043e\u0432\u044b\u0439 \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0412\u0435\u0447\u043d\u043e\u0441\u0442\u0438. \u041e\u043f\u0430\u0441\u0430\u044f\u0441\u044c, \u0447\u0442\u043e \u043e\u0434\u043d\u0430\u0436\u0434\u044b \u043e\u043d \u0432\u043d\u043e\u0432\u044c \u043f\u0440\u0438\u0437\u043e\u0432\u0435\u0442 \u041b\u0435\u0433\u0438\u043e\u043d, \u041c\u0430\u043b\u0444\u0443\u0440\u0438\u043e\u043d \u0438 \u041a\u0435\u043d\u0430\u0440\u0438\u0439 \u0437\u0430\u0442\u043e\u0447\u0438\u043b\u0438 \u0418\u043b\u043b\u0438\u0434\u0430\u043d\u0430 \u0432 Barrow Deeps, \u043f\u043e\u0434\u0437\u0435\u043c\u043d\u043e\u0439 \u0442\u0435\u043c\u043d\u0438\u0446\u0435, \u0433\u0434\u0435 \u043d\u0430\u0434\u0437\u0438\u0440\u0430\u0442\u0435\u043b\u044c\u043d\u0438\u0446\u0430 \u041c\u0430\u0439\u0435\u0432 \u041f\u0435\u0441\u043d\u044c \u0422\u0435\u043d\u0435\u0439 \u0441\u0442\u0435\u0440\u0435\u0433\u043b\u0430 \u0435\u0433\u043e \u0434\u0435\u0441\u044f\u0442\u044c \u0442\u044b\u0441\u044f\u0447 \u043b\u0435\u0442.","\u0422\u0440\u0438 \u0410\u0441\u043f\u0435\u043a\u0442\u0430, \u0410\u043b\u0435\u043a\u0441\u0442\u0440\u0430\u0437\u0430, \u0418\u0437\u0435\u0440\u0430 \u0438 \u041d\u043e\u0437\u0434\u043e\u0440\u043c\u0443, \u043e\u0442\u0432\u0435\u0442\u0438\u043b\u0438 \u043d\u0430 \u044d\u0442\u043e, \u0432\u044b\u0440\u0430\u0441\u0442\u0438\u0432 \u043d\u0430\u0434 \u043d\u043e\u0432\u044b\u043c \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c \u041d\u043e\u0440\u0434\u0440\u0430\u0441\u0441\u0438\u043b, \u0414\u0440\u0435\u0432\u043e \u041c\u0438\u0440\u0430. \u0415\u0433\u043e \u043a\u043e\u0440\u043d\u0438 \u0437\u0430\u043f\u0435\u0447\u0430\u0442\u0430\u043b\u0438 \u0432\u043e\u0434\u044b, \u0430 \u0435\u0433\u043e \u0431\u043b\u0430\u0433\u043e\u0441\u043b\u043e\u0432\u0435\u043d\u0438\u0435 \u0434\u0430\u0440\u043e\u0432\u0430\u043b\u043e \u043d\u043e\u0447\u043d\u044b\u043c \u044d\u043b\u044c\u0444\u0430\u043c \u0431\u0435\u0441\u0441\u043c\u0435\u0440\u0442\u0438\u0435, \u0430 \u0434\u0440\u0443\u0438\u0434\u0430\u043c \u2014 \u0441\u0432\u044f\u0437\u044c \u0441 \u0418\u0437\u0443\u043c\u0440\u0443\u0434\u043d\u044b\u043c \u0421\u043d\u043e\u043c, \u0433\u0434\u0435 \u043c\u043d\u043e\u0433\u0438\u0435 \u0438\u0437 \u043d\u0438\u0445 \u0441\u043f\u0430\u043b\u0438 \u0432\u0435\u043a\u0430\u043c\u0438. \u0422\u0438\u0440\u0430\u043d\u0434\u0430 \u0432\u043e\u0437\u0433\u043b\u0430\u0432\u0438\u043b\u0430 \u0421\u0435\u0441\u0442\u0435\u0440 \u042d\u043b\u0443\u043d\u044b \u0438 \u0427\u0430\u0441\u043e\u0432\u044b\u0445, \u043e\u0445\u0440\u0430\u043d\u044f\u0432\u0448\u0438\u0445 \u043b\u0435\u0441\u0430, \u043f\u043e\u043a\u0430 \u0434\u0440\u0443\u0438\u0434\u044b \u0432\u0438\u0434\u0435\u043b\u0438 \u0441\u043d\u044b. \u0422\u0430\u0439\u043d\u0430\u044f \u043c\u0430\u0433\u0438\u044f \u0431\u044b\u043b\u0430 \u0437\u0430\u043f\u0440\u0435\u0449\u0435\u043d\u0430 \u0441\u0440\u0435\u0434\u0438 \u043a\u0430\u043b\u0434\u043e\u0440\u0430\u0439.","\u041d\u0435 \u0432\u0441\u0435 \u0432\u044b\u0441\u043e\u043a\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u043d\u044b\u0435 \u043f\u043e\u0434\u0447\u0438\u043d\u0438\u043b\u0438\u0441\u044c. \u041e\u0434\u043d\u0438\u0445 \u0438\u0437\u0433\u043d\u0430\u043b\u0438 \u0437\u0430 \u043c\u043e\u0440\u0435, \u0438 \u043e\u043d\u0438 \u043e\u0441\u043d\u043e\u0432\u0430\u043b\u0438 \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441; \u0434\u0440\u0443\u0433\u0438\u0435, \u0448\u0435\u043d'\u0434\u0440\u0430\u043b\u0430\u0440, \u0443\u043a\u0440\u044b\u043b\u0438\u0441\u044c \u0432 \u0433\u043e\u0440\u043e\u0434\u0435 \u042d\u043b\u044c\u0434\u0440\u0435'\u0422\u0430\u043b\u0430\u0441 \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u043d\u044b\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u0424\u0435\u0440\u0430\u043b\u0430\u0441\u0430. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0435\u0433\u043e \u0440\u0443\u0438\u043d\u044b \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b \u043a\u0430\u043a \u0417\u0430\u0431\u044b\u0442\u044b\u0439 \u0433\u043e\u0440\u043e\u0434."]},"chapter:exiles-of-quelthalas":{title:"\u0418\u0437\u0433\u043d\u0430\u043d\u043d\u0438\u043a\u0438 \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441\u0430",summary:"\u0418\u0437\u0433\u043d\u0430\u043d\u043d\u044b\u0435 \u0432\u044b\u0441\u043e\u043a\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u0441\u0435\u043a\u043b\u0438 \u043c\u043e\u0440\u0435, \u0437\u0430\u0436\u0433\u043b\u0438 \u0421\u043e\u043b\u043d\u0435\u0447\u043d\u044b\u0439 \u041a\u043e\u043b\u043e\u0434\u0435\u0446 \u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u043b\u0438 \u044d\u043b\u044c\u0444\u0438\u0439\u0441\u043a\u043e\u0435 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u0432 \u0441\u0435\u0432\u0435\u0440\u043d\u044b\u0445 \u043b\u0435\u0441\u0430\u0445 \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d\u0430.",when:"\u041e\u043a\u043e\u043b\u043e 6800 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u0421\u043f\u0443\u0441\u0442\u044f \u0434\u043e\u043b\u0433\u043e\u0435 \u0432\u0440\u0435\u043c\u044f \u043f\u043e\u0441\u043b\u0435 \u0420\u0430\u0441\u043a\u043e\u043b\u0430 \u0433\u0440\u0443\u043f\u043f\u0430 \u0432\u044b\u0441\u043e\u043a\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u043d\u044b\u0445 \u0432\u0441\u0435 \u0435\u0449\u0435 \u043d\u0435 \u043c\u043e\u0433\u043b\u0430 \u043e\u0442\u043a\u0430\u0437\u0430\u0442\u044c\u0441\u044f \u043e\u0442 \u0442\u0430\u0439\u043d\u043e\u0439 \u043c\u0430\u0433\u0438\u0438. \u0418\u0445 \u0431\u0435\u0437\u0440\u0430\u0441\u0441\u0443\u0434\u043d\u044b\u0435 \u0447\u0430\u0440\u044b \u0432\u044b\u0437\u044b\u0432\u0430\u043b\u0438 \u0431\u0443\u0440\u0438 \u043d\u0430\u0434 \u042f\u0441\u0435\u043d\u0435\u0432\u044b\u043c \u043b\u0435\u0441\u043e\u043c, \u0438 \u0432 \u043a\u043e\u043d\u0446\u0435 \u043a\u043e\u043d\u0446\u043e\u0432 \u043d\u043e\u0447\u043d\u044b\u0435 \u044d\u043b\u044c\u0444\u044b \u0438\u0437\u0433\u043d\u0430\u043b\u0438 \u0438\u0445. \u0412\u043e \u0433\u043b\u0430\u0432\u0435 \u0441 \u0414\u0430\u0442'\u0420\u0435\u043c\u0430\u0440\u043e\u043c \u0421\u043e\u043b\u043d\u0435\u0447\u043d\u044b\u043c \u0421\u043a\u0438\u0442\u0430\u043b\u044c\u0446\u0435\u043c \u0438\u0437\u0433\u043d\u0430\u043d\u043d\u0438\u043a\u0438 \u043e\u0442\u043f\u043b\u044b\u043b\u0438 \u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a \u0447\u0435\u0440\u0435\u0437 \u0412\u0435\u043b\u0438\u043a\u043e\u0435 \u043c\u043e\u0440\u0435 \u0438 \u0433\u043e\u0434\u0430\u043c\u0438 \u0431\u0440\u043e\u0434\u0438\u043b\u0438 \u043f\u043e \u043d\u043e\u0432\u043e\u043c\u0443 \u043c\u0430\u0442\u0435\u0440\u0438\u043a\u0443 \u0432 \u043f\u043e\u0438\u0441\u043a\u0430\u0445 \u0437\u0435\u043c\u043b\u0438, \u0433\u0434\u0435 \u043c\u0430\u0433\u0438\u044f \u0442\u0435\u043a\u043b\u0430 \u0431\u044b \u043c\u043e\u0449\u043d\u044b\u043c \u043f\u043e\u0442\u043e\u043a\u043e\u043c.","\u041f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0437\u0430 6800 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430 \u043e\u043d\u0438 \u043d\u0430\u0448\u043b\u0438 \u0435\u0435 \u043d\u0430 \u0441\u0435\u0432\u0435\u0440\u0435 \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d\u0430. \u0414\u0430\u0442'\u0420\u0435\u043c\u0430\u0440 \u0432\u044b\u043b\u0438\u043b \u0443\u043a\u0440\u0430\u0434\u0435\u043d\u043d\u044b\u0439 \u0444\u0438\u0430\u043b \u0441 \u0432\u043e\u0434\u043e\u0439 \u0438\u0437 \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0412\u0435\u0447\u043d\u043e\u0441\u0442\u0438 \u0432 \u043e\u0437\u0435\u0440\u043e \u043d\u0430 \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u0441\u0438\u043b\u043e\u0432\u044b\u0445 \u043b\u0438\u043d\u0438\u0439, \u0438 \u0432\u0441\u043f\u044b\u0445\u043d\u0443\u043b \u0421\u043e\u043b\u043d\u0435\u0447\u043d\u044b\u0439 \u041a\u043e\u043b\u043e\u0434\u0435\u0446. \u0412\u043e\u043a\u0440\u0443\u0433 \u043d\u0435\u0433\u043e \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441 \u0438 \u0435\u0433\u043e \u0441\u0442\u043e\u043b\u0438\u0446\u0430 \u041b\u0443\u043d\u043e\u0441\u0432\u0435\u0442. \u0416\u0438\u0432\u044f \u043f\u043e\u0434 \u0441\u043e\u043b\u043d\u0446\u0435\u043c, \u0430 \u043d\u0435 \u043f\u043e\u0434 \u043b\u0443\u043d\u043e\u0439, \u0438\u0437\u0433\u043d\u0430\u043d\u043d\u0438\u043a\u0438 \u0437\u0430 \u0432\u0435\u043a\u0430 \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438\u0441\u044c \u0438 \u0441\u0442\u0430\u043b\u0438 \u0432\u044b\u0441\u0448\u0438\u043c\u0438 \u044d\u043b\u044c\u0444\u0430\u043c\u0438, \u043a\u0435\u043b\u044c'\u0434\u043e\u0440\u0430\u0439.","\u042d\u0442\u0430 \u0437\u0435\u043c\u043b\u044f \u043d\u0435 \u0431\u044b\u043b\u0430 \u043f\u0443\u0441\u0442\u043e\u0439. \u041d\u0430 \u043d\u0435\u0439 \u0441\u0442\u043e\u044f\u043b\u0438 \u0434\u0440\u0435\u0432\u043d\u0438\u0435 \u0440\u0443\u0438\u043d\u044b, \u0441\u0432\u044f\u0449\u0435\u043d\u043d\u044b\u0435 \u0434\u043b\u044f \u0442\u0440\u043e\u043b\u043b\u0435\u0439 \u0410\u043c\u0430\u043d\u0438, \u0438 \u0442\u0435 \u043e\u0431\u0440\u0443\u0448\u0438\u043b\u0438\u0441\u044c \u043d\u0430 \u043f\u0440\u0438\u0448\u0435\u043b\u044c\u0446\u0435\u0432 \u0432 \u043e\u0433\u0440\u043e\u043c\u043d\u043e\u043c \u0447\u0438\u0441\u043b\u0435. \u042d\u043b\u044c\u0444\u044b \u0441\u0434\u0435\u0440\u0436\u0430\u043b\u0438 \u0438\u0445 \u043c\u0430\u0433\u0438\u0435\u0439 \u0438 \u0432\u043e\u0437\u0432\u0435\u043b\u0438 \u0411\u0430\u043d'\u0434\u0438\u043d\u043e\u0440\u0438\u044d\u043b\u044c, \u0431\u0430\u0440\u044c\u0435\u0440 \u0438\u0437 \u0440\u0443\u043d\u043d\u044b\u0445 \u043a\u0430\u043c\u043d\u0435\u0439, \u043d\u0435 \u043f\u043e\u0434\u043f\u0443\u0441\u043a\u0430\u0432\u0448\u0438\u0439 \u0410\u043c\u0430\u043d\u0438. \u041e\u043a\u043e\u043b\u043e \u0447\u0435\u0442\u044b\u0440\u0435\u0445 \u0442\u044b\u0441\u044f\u0447 \u043b\u0435\u0442 \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441 \u043f\u0440\u043e\u0446\u0432\u0435\u0442\u0430\u043b \u043f\u043e\u0434 \u0435\u0433\u043e \u0437\u0430\u0449\u0438\u0442\u043e\u0439, \u0430 \u0442\u0440\u043e\u043b\u043b\u0438 \u0436\u0434\u0430\u043b\u0438 \u0447\u0430\u0441\u0430 \u043c\u0435\u0441\u0442\u0438."]},"chapter:arathor-and-the-troll-wars":{title:"\u0410\u0440\u0430\u0442\u043e\u0440 \u0438 \u0422\u0440\u043e\u043b\u043b\u044c\u0438 \u0432\u043e\u0439\u043d\u044b",summary:"\u0420\u0430\u0437\u0440\u043e\u0437\u043d\u0435\u043d\u043d\u044b\u0435 \u043f\u043b\u0435\u043c\u0435\u043d\u0430 \u043b\u044e\u0434\u0435\u0439 \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0438\u043b\u0438\u0441\u044c \u043f\u043e\u0434 \u0432\u043b\u0430\u0441\u0442\u044c\u044e \u043a\u043e\u0440\u043e\u043b\u044f \u0422\u043e\u0440\u0430\u0434\u0438\u043d\u0430, \u0430 \u0441\u043e\u044e\u0437 \u0441 \u044d\u043b\u044c\u0444\u0430\u043c\u0438 \u0441\u043e\u043a\u0440\u0443\u0448\u0438\u043b \u0438\u043c\u043f\u0435\u0440\u0438\u044e \u0410\u043c\u0430\u043d\u0438 \u0443 \u043f\u043e\u0434\u043d\u043e\u0436\u0438\u044f \u0410\u043b\u044c\u0442\u0435\u0440\u0430\u043a\u0441\u043a\u0438\u0445 \u0433\u043e\u0440.",when:"\u041e\u043a\u043e\u043b\u043e 2800 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u0422\u044b\u0441\u044f\u0447\u0435\u043b\u0435\u0442\u0438\u044f\u043c\u0438 \u043f\u043b\u0435\u043c\u0435\u043d\u0430 \u043b\u044e\u0434\u0435\u0439 \u0412\u043e\u0441\u0442\u043e\u0447\u043d\u044b\u0445 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432 \u0432\u043e\u0435\u0432\u0430\u043b\u0438 \u0434\u0440\u0443\u0433 \u0441 \u0434\u0440\u0443\u0433\u043e\u043c, \u0430 \u0441 \u0441\u0435\u0432\u0435\u0440\u0430 \u043d\u0430\u043f\u0430\u0434\u0430\u043b\u0438 \u043d\u0430\u043b\u0435\u0442\u0447\u0438\u043a\u0438 \u0410\u043c\u0430\u043d\u0438. \u041f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0437\u0430 2800 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430 \u0422\u043e\u0440\u0430\u0434\u0438\u043d \u0438\u0437 \u043f\u043b\u0435\u043c\u0435\u043d\u0438 \u0410\u0440\u0430\u0442\u0438 \u043f\u043e\u043d\u044f\u043b, \u0447\u0442\u043e \u0440\u0430\u0437\u043e\u0431\u0449\u0435\u043d\u043d\u043e\u0435 \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u0442\u0432\u043e \u043f\u043e\u0433\u0438\u0431\u043d\u0435\u0442. \u0411\u0440\u0430\u043a\u0430\u043c\u0438, \u043e\u0431\u0435\u0449\u0430\u043d\u0438\u044f\u043c\u0438 \u0438 \u0437\u0430\u0432\u043e\u0435\u0432\u0430\u043d\u0438\u044f\u043c\u0438 \u043e\u043d \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0438\u043b \u043f\u043b\u0435\u043c\u0435\u043d\u0430 \u0432 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u0410\u0440\u0430\u0442\u043e\u0440 \u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u043b \u0435\u0433\u043e \u0441\u0442\u043e\u043b\u0438\u0446\u0443, \u0433\u043e\u0440\u043e\u0434-\u043a\u0440\u0435\u043f\u043e\u0441\u0442\u044c \u0421\u0442\u0440\u043e\u043c, \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u043d\u044b\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u041d\u0430\u0433\u043e\u0440\u044c\u044f \u0410\u0440\u0430\u0442\u0438.","\u0410\u043c\u0430\u043d\u0438, \u0432\u043d\u043e\u0432\u044c \u043d\u0430\u0431\u0440\u0430\u0432\u0448\u0438\u0435\u0441\u044f \u0441\u0438\u043b \u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e \u0437\u0430\u043d\u0434\u0430\u043b\u0430\u0440\u043e\u0432, \u043e\u0433\u0440\u043e\u043c\u043d\u044b\u043c \u0432\u043e\u0439\u0441\u043a\u043e\u043c \u043e\u0431\u0440\u0443\u0448\u0438\u043b\u0438\u0441\u044c \u043d\u0430 \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441. \u042d\u043b\u044c\u0444\u044b \u043e\u0431\u0440\u0430\u0442\u0438\u043b\u0438\u0441\u044c \u043a \u0410\u0440\u0430\u0442\u043e\u0440\u0443. \u0412 \u043e\u0431\u043c\u0435\u043d \u043d\u0430 \u0432\u043e\u0438\u043d\u043e\u0432-\u043b\u044e\u0434\u0435\u0439 \u043e\u043d\u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u043b\u0438\u0441\u044c \u043e\u0431\u0443\u0447\u0438\u0442\u044c \u043c\u0430\u0433\u0438\u0438 \u0441\u043e\u0442\u043d\u044e \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u044b\u0445 \u043b\u044e\u0434\u0435\u0439 \u2014 \u043f\u0435\u0440\u0432\u044b\u0445 \u043c\u0430\u0433\u043e\u0432 \u0441\u0440\u0435\u0434\u0438 \u043b\u044e\u0434\u0435\u0439. \u0412\u043c\u0435\u0441\u0442\u0435 \u044d\u043b\u044c\u0444\u044b \u0438 \u043b\u044e\u0434\u0438 \u0440\u0430\u0437\u0433\u0440\u043e\u043c\u0438\u043b\u0438 \u0430\u0440\u043c\u0438\u044e \u0410\u043c\u0430\u043d\u0438 \u0443 \u043f\u043e\u0434\u043d\u043e\u0436\u0438\u044f \u0410\u043b\u044c\u0442\u0435\u0440\u0430\u043a\u0441\u043a\u0438\u0445 \u0433\u043e\u0440, \u0438 \u043e\u0433\u043e\u043d\u044c \u043c\u0430\u0433\u043e\u0432 \u0442\u0430\u043a \u0440\u0430\u0441\u0441\u0435\u044f\u043b \u0442\u0440\u043e\u043b\u043b\u0435\u0439, \u0447\u0442\u043e \u0438\u0445 \u0438\u043c\u043f\u0435\u0440\u0438\u044f \u0443\u0436\u0435 \u043d\u0435 \u043e\u043f\u0440\u0430\u0432\u0438\u043b\u0430\u0441\u044c.","\u0412 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u043d\u043e\u0441\u0442\u044c \u044d\u043b\u044c\u0444\u044b \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441\u0430 \u043f\u043e\u043a\u043b\u044f\u043b\u0438\u0441\u044c \u0432 \u0432\u0435\u0440\u043d\u043e\u0441\u0442\u0438 \u0440\u043e\u0434\u0443 \u043a\u043e\u0440\u043e\u043b\u0435\u0439 \u0410\u0440\u0430\u0442\u043e\u0440\u0430. \u0421\u0442\u0440\u043e\u043c \u043f\u0440\u043e\u0446\u0432\u0435\u0442\u0430\u043b, \u0438 \u0435\u0433\u043e \u043d\u0430\u0440\u043e\u0434 \u0440\u0430\u0441\u0441\u0435\u043b\u0438\u043b\u0441\u044f \u043f\u043e \u0432\u0441\u0435\u043c\u0443 \u0441\u0435\u0432\u0435\u0440\u0443. \u0410\u043c\u0430\u043d\u0438 \u0435\u0449\u0435 \u043d\u0435 \u0440\u0430\u0437 \u043f\u043e\u0434\u043d\u0438\u043c\u0443\u0442\u0441\u044f \u0432\u043d\u043e\u0432\u044c, \u0438 \u0432\u043e \u0412\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0445 \u0437\u0435\u043c\u043b\u044f\u0445 \u0438 \u043d\u0430 \u041d\u0430\u0433\u043e\u0440\u044c\u0435 \u0410\u0440\u0430\u0442\u0438 \u043f\u043b\u0435\u043c\u0435\u043d\u0430 \u043b\u0435\u0441\u043d\u044b\u0445 \u0442\u0440\u043e\u043b\u043b\u0435\u0439 \u0434\u043e \u0441\u0438\u0445 \u043f\u043e\u0440 \u0431\u0440\u043e\u0434\u044f\u0442 \u0441\u0440\u0435\u0434\u0438 \u0440\u0443\u0438\u043d \u0442\u043e\u0439 \u0434\u0430\u0432\u043d\u0435\u0439 \u0432\u043e\u0439\u043d\u044b."]},"chapter:guardians-and-the-seven-kingdoms":{title:"\u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u0438 \u0438 \u0421\u0435\u043c\u044c \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432",summary:"\u041c\u0430\u0433\u0438\u044f \u043b\u044e\u0434\u0435\u0439 \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u043b\u0430 \u0434\u0435\u043c\u043e\u043d\u043e\u0432, \u0438 \u043c\u0430\u0433\u0438 \u043e\u0441\u043d\u043e\u0432\u0430\u043b\u0438 \u0414\u0430\u043b\u0430\u0440\u0430\u043d \u0438 \u0441\u0442\u0430\u043b\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u0442\u044c \u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u0435\u0439 \u0434\u043b\u044f \u0442\u0430\u0439\u043d\u043e\u0439 \u0431\u043e\u0440\u044c\u0431\u044b, \u0430 \u0410\u0440\u0430\u0442\u043e\u0440 \u0440\u0430\u0441\u043f\u0430\u043b\u0441\u044f \u043d\u0430 \u0441\u0435\u043c\u044c \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432.",when:"\u0422\u044b\u0441\u044f\u0447\u0435\u043b\u0435\u0442\u0438\u044f \u043f\u043e\u0441\u043b\u0435 \u0422\u0440\u043e\u043b\u043b\u044c\u0438\u0445 \u0432\u043e\u0439\u043d",body:["\u041c\u0430\u0433\u0438\u044f \u0440\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u044f\u043b\u0430\u0441\u044c \u0432 \u0410\u0440\u0430\u0442\u043e\u0440\u0435 \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u043c\u0443\u0434\u0440\u043e\u0441\u0442\u0438. \u0417\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u044f \u043c\u0430\u0433\u043e\u0432 \u0438\u0441\u0442\u043e\u043d\u0447\u0438\u043b\u0438 \u0441\u0442\u0435\u043d\u044b \u043c\u0438\u0440\u0430 \u0438 \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u043b\u0438 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u0434\u0435\u043c\u043e\u043d\u043e\u0432, \u0438 \u0442\u043e\u0433\u0434\u0430 \u0432\u044b\u0441\u0448\u0438\u0435 \u044d\u043b\u044c\u0444\u044b \u0438 \u043c\u0430\u0433\u0438-\u043b\u044e\u0434\u0438 \u0443\u0447\u0440\u0435\u0434\u0438\u043b\u0438 \u0421\u043e\u0432\u0435\u0442 \u0422\u0438\u0440\u0438\u0441\u0444\u0430\u043b\u044f. \u0412\u0442\u0430\u0439\u043d\u0435 \u0441\u043e\u0432\u0435\u0442 \u0438\u0437\u0431\u0438\u0440\u0430\u043b \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u044f, \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u0432\u0432\u0435\u0440\u044f\u043b\u0430\u0441\u044c \u0438\u0445 \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u043d\u0430\u044f \u0441\u0438\u043b\u0430 \u0434\u043b\u044f \u043e\u0445\u043e\u0442\u044b \u043d\u0430 \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u041f\u044b\u043b\u0430\u044e\u0449\u0435\u0433\u043e \u041b\u0435\u0433\u0438\u043e\u043d\u0430.","\u041c\u0430\u0433\u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u043b\u0438 \u0438 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0433\u043e\u0440\u043e\u0434, \u0414\u0430\u043b\u0430\u0440\u0430\u043d, \u0433\u0434\u0435 \u0434\u043e\u043b\u0436\u0435\u043d \u0431\u044b\u043b \u043f\u0440\u0430\u0432\u0438\u0442\u044c \u041a\u0438\u0440\u0438\u043d-\u0422\u043e\u0440. \u0422\u0435\u043c \u0432\u0440\u0435\u043c\u0435\u043d\u0435\u043c \u043d\u0430\u0441\u043b\u0435\u0434\u043d\u0438\u043a\u0438 \u0410\u0440\u0430\u0442\u043e\u0440\u0430 \u043f\u043e\u043a\u0438\u043d\u0443\u043b\u0438 \u0421\u0442\u0440\u043e\u043c, \u0438 \u0437\u0430 \u0432\u0435\u043a\u0430 \u0438\u043c\u043f\u0435\u0440\u0438\u044f \u0440\u0430\u0441\u043f\u0430\u043b\u0430\u0441\u044c \u043d\u0430 \u0441\u0435\u043c\u044c \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432: \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d, \u0421\u0442\u0440\u043e\u043c\u0433\u0430\u0440\u0434, \u0413\u0438\u043b\u043d\u0435\u0430\u0441, \u0410\u043b\u044c\u0442\u0435\u0440\u0430\u043a, \u041a\u0443\u043b-\u0422\u0438\u0440\u0430\u0441, \u0414\u0430\u043b\u0430\u0440\u0430\u043d \u0438, \u043d\u0430 \u044e\u0433\u0435, \u0428\u0442\u043e\u0440\u043c\u0433\u0440\u0430\u0434, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0434\u043e\u043b\u0433\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e\u043c \u0410\u0437\u0435\u0440\u043e\u0442.","\u0421\u0430\u043c\u043e\u0439 \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0439 \u0438\u0437 \u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u0435\u0439 \u0431\u044b\u043b\u0430 \u042d\u0433\u0432\u0438\u043d, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0432 \u041d\u043e\u0440\u0434\u0441\u043a\u043e\u043b\u0435 \u0441\u0440\u0430\u0437\u0438\u043b\u0430 \u0430\u0432\u0430\u0442\u0430\u0440\u0443 \u0441\u0430\u043c\u043e\u0433\u043e \u0421\u0430\u0440\u0433\u0435\u0440\u0430\u0441\u0430 \u0438 \u0437\u0430\u043f\u0435\u0447\u0430\u0442\u0430\u043b\u0430 \u0435\u0433\u043e \u0442\u0435\u043b\u043e \u0432 \u0433\u0440\u043e\u0431\u043d\u0438\u0446\u0435 \u043d\u0430 \u0434\u043d\u0435 \u043c\u043e\u0440\u044f. \u041e\u043d\u0430 \u0442\u0430\u043a \u0438 \u043d\u0435 \u0443\u0437\u043d\u0430\u043b\u0430, \u0447\u0442\u043e \u0434\u0443\u0445 \u0442\u0435\u043c\u043d\u043e\u0433\u043e \u0442\u0438\u0442\u0430\u043d\u0430 \u043f\u0440\u043e\u043d\u0438\u043a \u0432 \u043d\u0435\u0435. \u041a\u043e\u0433\u0434\u0430 \u0443 \u043d\u0435\u0435 \u0440\u043e\u0434\u0438\u043b\u0441\u044f \u0441\u044b\u043d \u041c\u0435\u0434\u0438\u0432, \u0434\u0443\u0445 \u043f\u0435\u0440\u0435\u0448\u0435\u043b \u043a \u043d\u0435\u043c\u0443, \u0438 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u044c \u0432\u044b\u0440\u043e\u0441 \u0441 \u0437\u0430\u0442\u0430\u0438\u0432\u0448\u0438\u043c\u0441\u044f \u0432 \u0434\u0443\u0448\u0435 \u043f\u0440\u0435\u0434\u0430\u0442\u0435\u043b\u0435\u043c. \u041e\u0434\u043d\u0430\u0436\u0434\u044b \u0438\u0437 \u0441\u0432\u043e\u0435\u0439 \u0431\u0430\u0448\u043d\u0438 \u041a\u0430\u0440\u0430\u0436\u0430\u043d \u043e\u043d \u043e\u0442\u043a\u0440\u043e\u0435\u0442 \u0434\u0432\u0435\u0440\u044c \u043e\u0440\u043a\u0430\u043c."]},"chapter:war-of-the-three-hammers":{title:"\u0412\u043e\u0439\u043d\u0430 \u0422\u0440\u0435\u0445 \u041c\u043e\u043b\u043e\u0442\u043e\u0432",summary:"\u0422\u0440\u0438 \u043a\u043b\u0430\u043d\u0430 \u0434\u0432\u043e\u0440\u0444\u043e\u0432 \u0421\u0442\u0430\u043b\u044c\u0433\u043e\u0440\u043d\u0430 \u0441\u0440\u0430\u0436\u0430\u043b\u0438\u0441\u044c \u0437\u0430 \u0442\u0440\u043e\u043d, \u0438 \u043f\u043e\u0431\u0435\u0436\u0434\u0435\u043d\u043d\u044b\u0439 \u0442\u0430\u043d-\u0447\u0430\u0440\u043e\u0434\u0435\u0439 \u043f\u0440\u0438\u0437\u0432\u0430\u043b \u0420\u0430\u0433\u043d\u0430\u0440\u043e\u0441\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u044b\u0436\u0435\u0433 \u0437\u0435\u043c\u043b\u044e \u0438 \u0432\u043e\u0437\u0434\u0432\u0438\u0433 \u0427\u0435\u0440\u043d\u0443\u044e \u0433\u043e\u0440\u0443.",when:"\u041e\u043a\u043e\u043b\u043e 230 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u041f\u043e\u0434 \u0441\u043d\u0435\u0433\u0430\u043c\u0438 \u0414\u0443\u043d \u041c\u043e\u0440\u043e\u0433\u0430 \u0434\u0432\u043e\u0440\u0444\u044b \u0432\u044b\u0441\u0435\u043a\u043b\u0438 \u0421\u0442\u0430\u043b\u044c\u0433\u043e\u0440\u043d, \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043a\u0430\u043c\u043d\u044f \u0438 \u0440\u0435\u043c\u0435\u0441\u043b\u0430, \u0447\u044c\u0438 \u043a\u043e\u0440\u043d\u0438 \u0432\u043e\u0441\u0445\u043e\u0434\u0438\u043b\u0438 \u043a \u0437\u0435\u043c\u0435\u043b\u044c\u043d\u0438\u043a\u0430\u043c \u0442\u0438\u0442\u0430\u043d\u043e\u0432. \u0422\u0440\u0438 \u043a\u043b\u0430\u043d\u0430 \u0441 \u0442\u0440\u0443\u0434\u043e\u043c \u0443\u0436\u0438\u0432\u0430\u043b\u0438\u0441\u044c \u0432 \u043d\u0435\u043c: \u0411\u0440\u043e\u043d\u0437\u043e\u0431\u043e\u0440\u043e\u0434\u044b, \u0413\u0440\u043e\u043c\u043e\u0432\u044b\u0435 \u041c\u043e\u043b\u043e\u0442\u044b \u0438 \u0427\u0435\u0440\u043d\u043e\u0435 \u0416\u0435\u043b\u0435\u0437\u043e, \u043f\u0438\u0442\u0430\u0432\u0448\u0435\u0435 \u0441\u0442\u0440\u0430\u0441\u0442\u044c \u043a \u0447\u0430\u0440\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0443. \u041a\u043e\u0433\u0434\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0437\u0430 230 \u043b\u0435\u0442 \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430 \u0443\u043c\u0435\u0440 \u0432\u0435\u0440\u0445\u043e\u0432\u043d\u044b\u0439 \u043a\u043e\u0440\u043e\u043b\u044c \u041c\u043e\u0434\u0438\u043c\u0443\u0441 \u0410\u043d\u0432\u0438\u043b\u043c\u0430\u0440, \u0438\u0445 \u0441\u043e\u043f\u0435\u0440\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u043f\u0435\u0440\u0435\u0440\u043e\u0441\u043b\u043e \u0432 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u043a\u0443\u044e \u0432\u043e\u0439\u043d\u0443.","\u0411\u0440\u043e\u043d\u0437\u043e\u0431\u043e\u0440\u043e\u0434\u044b \u043f\u043e\u0431\u0435\u0434\u0438\u043b\u0438 \u0438 \u0438\u0437\u0433\u043d\u0430\u043b\u0438 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445. \u0413\u0440\u043e\u043c\u043e\u0432\u044b\u0435 \u041c\u043e\u043b\u043e\u0442\u044b \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u043b\u0438 \u0413\u0440\u0438\u043c \u0411\u0430\u0442\u043e\u043b \u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a\u0435, \u0430 \u0434\u0432\u043e\u0440\u0444\u044b \u0427\u0435\u0440\u043d\u043e\u0433\u043e \u0416\u0435\u043b\u0435\u0437\u0430 \u043e\u0441\u043d\u043e\u0432\u0430\u043b\u0438 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043d\u0430 \u044e\u0433\u0435, \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u0433\u043e\u0440\u044c\u0435. \u0422\u0430\u043d-\u0447\u0430\u0440\u043e\u0434\u0435\u0439 \u0422\u0430\u0443\u0440\u0438\u0441\u0441\u0430\u043d \u043d\u0435 \u0441\u043c\u0438\u0440\u0438\u043b\u0441\u044f \u0441 \u043f\u043e\u0440\u0430\u0436\u0435\u043d\u0438\u0435\u043c. \u041e\u043d \u0443\u0434\u0430\u0440\u0438\u043b \u043f\u043e \u043e\u0431\u043e\u0438\u043c \u0441\u043e\u043f\u0435\u0440\u043d\u0438\u043a\u0430\u043c \u0441\u0440\u0430\u0437\u0443, \u043d\u043e \u0435\u0433\u043e \u0430\u0440\u043c\u0438\u0438 \u0431\u044b\u043b\u0438 \u0440\u0430\u0437\u0431\u0438\u0442\u044b, \u0430 \u0435\u0433\u043e \u0436\u0435\u043d\u0430 \u041c\u043e\u0434\u0433\u0443\u0434 \u043f\u0430\u043b\u0430 \u0443 \u0413\u0440\u0438\u043c \u0411\u0430\u0442\u043e\u043b\u0430.","\u0412 \u043e\u0442\u0447\u0430\u044f\u043d\u0438\u0438 \u0422\u0430\u0443\u0440\u0438\u0441\u0441\u0430\u043d \u043f\u043e\u0442\u044f\u043d\u0443\u043b\u0441\u044f \u043a \u0441\u0438\u043b\u0435 \u0431\u043e\u043b\u044c\u0448\u0435\u0439 \u0438 \u043f\u0440\u0438\u0437\u0432\u0430\u043b \u0420\u0430\u0433\u043d\u0430\u0440\u043e\u0441\u0430, \u041f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u044f \u041e\u0433\u043d\u044f, \u043f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u044f \u0441\u0442\u0438\u0445\u0438\u0439, \u0437\u0430\u0442\u043e\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u0442\u0438\u0442\u0430\u043d\u0430\u043c\u0438. \u042f\u0432\u043b\u0435\u043d\u0438\u0435 \u041f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u044f \u041e\u0433\u043d\u044f \u0443\u0431\u0438\u043b\u043e \u0442\u0430\u043d\u0430, \u0440\u0430\u0437\u043e\u0440\u0432\u0430\u043b\u043e \u0437\u0435\u043c\u043b\u044e, \u0441\u043e\u0437\u0434\u0430\u0432 \u0422\u043b\u0435\u044e\u0449\u0435\u0435 \u0443\u0449\u0435\u043b\u044c\u0435 \u0438 \u041f\u044b\u043b\u0430\u044e\u0449\u0438\u0435 \u0441\u0442\u0435\u043f\u0438, \u0438 \u0432\u0437\u0434\u044b\u0431\u0438\u043b\u043e \u0427\u0435\u0440\u043d\u0443\u044e \u0433\u043e\u0440\u0443, \u0433\u0434\u0435 \u0432\u044b\u0436\u0438\u0432\u0448\u0438\u0435 \u0434\u0432\u043e\u0440\u0444\u044b \u0427\u0435\u0440\u043d\u043e\u0433\u043e \u0416\u0435\u043b\u0435\u0437\u0430 \u0441\u0442\u0430\u043b\u0438 \u0435\u0433\u043e \u0440\u0430\u0431\u0430\u043c\u0438. \u0413\u0440\u043e\u043c\u043e\u0432\u044b\u0435 \u041c\u043e\u043b\u043e\u0442\u044b \u043f\u043e\u043a\u0438\u043d\u0443\u043b\u0438 \u043f\u0440\u043e\u043a\u043b\u044f\u0442\u044b\u0439 \u0413\u0440\u0438\u043c \u0411\u0430\u0442\u043e\u043b \u0438 \u0443\u0448\u043b\u0438 \u0432\u043e \u0412\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0435 \u0437\u0435\u043c\u043b\u0438. \u0418\u0445 \u0441\u043e\u0441\u0435\u0434\u0438-\u0433\u043d\u043e\u043c\u044b, \u0447\u0435\u0439 \u0433\u043e\u0440\u043e\u0434 \u0413\u043d\u043e\u043c\u0440\u0435\u0433\u0430\u043d \u043d\u0430\u0445\u043e\u0434\u0438\u043b\u0441\u044f \u043d\u0435\u043f\u043e\u0434\u0430\u043b\u0435\u043a\u0443, \u0441\u0442\u0430\u043b\u0438 \u0432\u0435\u0440\u043d\u044b\u043c\u0438 \u0434\u0440\u0443\u0437\u044c\u044f\u043c\u0438 \u0421\u0442\u0430\u043b\u044c\u0433\u043e\u0440\u043d\u0430."]},"chapter:corruption-of-the-orcs":{title:"\u041f\u043e\u0440\u0447\u0430 \u043e\u0440\u043a\u043e\u0432",summary:"\u0412 \u0434\u0430\u043b\u0435\u043a\u043e\u043c \u0414\u0440\u0435\u043d\u043e\u0440\u0435 \u041a\u0438\u043b'\u0434\u0436\u0435\u0434\u0435\u043d \u043f\u0440\u0435\u0432\u0440\u0430\u0442\u0438\u043b \u0448\u0430\u043c\u0430\u043d\u0441\u043a\u0438\u0435 \u043a\u043b\u0430\u043d\u044b \u043e\u0440\u043a\u043e\u0432 \u0432 \u043a\u0440\u043e\u0432\u043e\u0436\u0430\u0434\u043d\u0443\u044e \u041e\u0440\u0434\u0443, \u0441\u043a\u043e\u0432\u0430\u043d\u043d\u0443\u044e \u0434\u0435\u043c\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043a\u0440\u043e\u0432\u044c\u044e.",when:"\u0414\u0435\u0441\u044f\u0442\u0438\u043b\u0435\u0442\u0438\u044f \u0434\u043e \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u0412 \u043c\u0438\u0440\u0435 \u0414\u0440\u0435\u043d\u043e\u0440 \u043e\u0440\u043a\u0438 \u0436\u0438\u043b\u0438 \u0433\u043e\u0440\u0434\u044b\u043c\u0438 \u043a\u043b\u0430\u043d\u0430\u043c\u0438 \u043e\u0445\u043e\u0442\u043d\u0438\u043a\u043e\u0432 \u0438 \u0448\u0430\u043c\u0430\u043d\u043e\u0432, \u0447\u0442\u0438\u043b\u0438 \u043f\u0440\u0435\u0434\u043a\u043e\u0432 \u0438 \u0434\u0443\u0445\u043e\u0432 \u0441\u0442\u0438\u0445\u0438\u0439. \u041e\u043d\u0438 \u043d\u0435\u043f\u0440\u043e\u0441\u0442\u043e \u0434\u0435\u043b\u0438\u043b\u0438 \u0441\u0432\u043e\u0439 \u043c\u0438\u0440 \u0441 \u0434\u0440\u0435\u043d\u0435\u044f\u043c\u0438 \u2014 \u044d\u0440\u0435\u0434\u0430\u0440\u0430\u043c\u0438, \u0431\u0435\u0436\u0430\u0432\u0448\u0438\u043c\u0438 \u0441 \u0410\u0440\u0433\u0443\u0441\u0430 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u0412\u0435\u043b\u0435\u043d\u043e\u043c. \u041a\u0438\u043b'\u0434\u0436\u0435\u0434\u0435\u043d \u043d\u0435 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u0432\u0430\u043b \u043e\u0445\u043e\u0442\u0438\u0442\u044c\u0441\u044f \u043d\u0430 \u044d\u0442\u0438\u0445 \u0438\u0437\u0433\u043d\u0430\u043d\u043d\u0438\u043a\u043e\u0432 \u0438 \u0443\u0432\u0438\u0434\u0435\u043b \u0432 \u043e\u0440\u043a\u0430\u0445 \u043e\u0440\u0443\u0436\u0438\u0435.","\u041f\u0440\u0438\u043d\u044f\u0432 \u043e\u0431\u043b\u0438\u043a \u0434\u0443\u0445\u0430 \u0443\u043c\u0435\u0440\u0448\u0435\u0439 \u0436\u0435\u043d\u044b \u041d\u0435\u0440'\u0437\u0443\u043b\u0430, \u043f\u043e\u0432\u0435\u043b\u0438\u0442\u0435\u043b\u044c \u0434\u0435\u043c\u043e\u043d\u043e\u0432 \u043d\u0430\u0448\u0435\u043f\u0442\u044b\u0432\u0430\u043b \u0441\u0442\u0430\u0440\u043e\u043c\u0443 \u0448\u0430\u043c\u0430\u043d\u0443 \u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0438\u043b \u0435\u0433\u043e \u043f\u0440\u043e\u0442\u0438\u0432 \u0434\u0440\u0435\u043d\u0435\u0435\u0432. \u041a\u043e\u0433\u0434\u0430 \u041d\u0435\u0440'\u0437\u0443\u043b \u0437\u0430\u043a\u043e\u043b\u0435\u0431\u0430\u043b\u0441\u044f, \u041a\u0438\u043b'\u0434\u0436\u0435\u0434\u0435\u043d \u043d\u0430\u0448\u0435\u043b \u0431\u043e\u043b\u0435\u0435 \u043f\u043e\u0441\u043b\u0443\u0448\u043d\u043e\u0433\u043e \u0443\u0447\u0435\u043d\u0438\u043a\u0430 \u0432 \u0413\u0443\u043b'\u0434\u0430\u043d\u0435, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u0441\u043d\u043e\u0432\u0430\u043b \u0442\u0430\u0439\u043d\u044b\u0439 \u0421\u043e\u0432\u0435\u0442 \u0422\u0435\u043d\u0435\u0439 \u0438 \u043e\u0431\u0443\u0447\u0438\u043b \u043e\u0440\u043a\u043e\u0432 \u043c\u0430\u0433\u0438\u0438 \u0421\u043a\u0432\u0435\u0440\u043d\u044b; \u0442\u0430\u043a \u043f\u043e\u044f\u0432\u0438\u043b\u0438\u0441\u044c \u043f\u0435\u0440\u0432\u044b\u0435 \u0447\u0435\u0440\u043d\u043e\u043a\u043d\u0438\u0436\u043d\u0438\u043a\u0438. \u0421\u0442\u0438\u0445\u0438\u0438 \u0443\u043c\u043e\u043b\u043a\u043b\u0438, \u0438 \u0437\u0435\u043b\u0435\u043d\u0430\u044f \u0437\u0435\u043c\u043b\u044f \u043e\u0440\u043a\u043e\u0432 \u043d\u0430\u0447\u0430\u043b\u0430 \u0443\u043c\u0438\u0440\u0430\u0442\u044c.","\u041d\u0430 \u0432\u0435\u043b\u0438\u043a\u043e\u043c \u0441\u0431\u043e\u0440\u0438\u0449\u0435 \u0432\u043e\u0436\u0434\u0438 \u043a\u043b\u0430\u043d\u043e\u0432 \u0438\u0441\u043f\u0438\u043b\u0438 \u043a\u0440\u043e\u0432\u0438 \u0432\u043b\u0430\u0434\u044b\u043a\u0438 \u043f\u0440\u0435\u0438\u0441\u043f\u043e\u0434\u043d\u0435\u0439 \u041c\u0430\u043d\u043d\u043e\u0440\u043e\u0445\u0430, \u0438 \u043f\u0435\u0440\u0432\u044b\u043c \u043f\u0438\u043b \u0413\u0440\u043e\u043c \u0410\u0434\u0441\u043a\u0438\u0439 \u041a\u0440\u0438\u043a \u0438\u0437 \u043a\u043b\u0430\u043d\u0430 \u041f\u0435\u0441\u043d\u0438 \u0412\u043e\u0439\u043d\u044b. \u041e\u0431\u044a\u044f\u0442\u0430\u044f \u0434\u0435\u043c\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u044f\u0440\u043e\u0441\u0442\u044c\u044e, \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u043d\u0430\u044f \u041e\u0440\u0434\u0430 \u043e\u0431\u0440\u0443\u0448\u0438\u043b\u0430\u0441\u044c \u043d\u0430 \u0434\u0440\u0435\u043d\u0435\u0435\u0432 \u0438 \u0435\u0434\u0432\u0430 \u043d\u0435 \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u043b\u0430 \u0438\u0445. \u041b\u0438\u0448\u044c \u043a\u043b\u0430\u043d \u0421\u0435\u0432\u0435\u0440\u043d\u043e\u0433\u043e \u0412\u043e\u043b\u043a\u0430 \u0414\u0443\u0440\u043e\u0442\u0430\u043d\u0430 \u043e\u0442\u0447\u0430\u0441\u0442\u0438 \u0434\u0435\u0440\u0436\u0430\u043b\u0441\u044f \u0432 \u0441\u0442\u043e\u0440\u043e\u043d\u0435. \u041a\u043e\u0433\u0434\u0430 \u0440\u0435\u0437\u043d\u044f \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u0430\u0441\u044c, \u0413\u0443\u043b'\u0434\u0430\u043d\u0443 \u043f\u043e\u043d\u0430\u0434\u043e\u0431\u0438\u043b\u0430\u0441\u044c \u043d\u043e\u0432\u0430\u044f \u0432\u043e\u0439\u043d\u0430, \u0438 \u0443 \u0433\u043e\u0441\u043f\u043e\u0434\u0438\u043d\u0430 \u041a\u0438\u043b'\u0434\u0436\u0435\u0434\u0435\u043d\u0430 \u043e\u043d\u0430 \u0443\u0436\u0435 \u0431\u044b\u043b\u0430 \u043d\u0430\u0433\u043e\u0442\u043e\u0432\u0435 \u2014 \u043d\u0430 \u0410\u0437\u0435\u0440\u043e\u0442\u0435."]},"chapter:the-first-war":{title:"\u0422\u0435\u043c\u043d\u044b\u0439 \u043f\u043e\u0440\u0442\u0430\u043b \u0438 \u041f\u0435\u0440\u0432\u0430\u044f \u0432\u043e\u0439\u043d\u0430",summary:"\u041c\u0435\u0434\u0438\u0432 \u043f\u043e\u043c\u043e\u0433 \u043e\u0440\u043a\u0430\u043c \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u0422\u0435\u043c\u043d\u044b\u0439 \u043f\u043e\u0440\u0442\u0430\u043b, \u0438 \u041e\u0440\u0434\u0430 \u0437\u0430\u0445\u0432\u0430\u0442\u0438\u043b\u0430 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u0428\u0442\u043e\u0440\u043c\u0433\u0440\u0430\u0434.",when:"\u0413\u043e\u0434 0: \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0422\u0435\u043c\u043d\u044b\u0439 \u043f\u043e\u0440\u0442\u0430\u043b",body:["\u041f\u043e\u0434 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e\u043c \u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0433\u043e \u041c\u0435\u0434\u0438\u0432\u0430 \u0447\u0435\u0440\u043d\u043e\u043a\u043d\u0438\u0436\u043d\u0438\u043a\u0438 \u0413\u0443\u043b'\u0434\u0430\u043d\u0430 \u0438 \u0441\u0430\u043c \u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u044c \u043e\u0442\u043a\u0440\u044b\u043b\u0438 \u0440\u0430\u0437\u043b\u043e\u043c \u043c\u0435\u0436\u0434\u0443 \u0414\u0440\u0435\u043d\u043e\u0440\u043e\u043c \u0438 \u0410\u0437\u0435\u0440\u043e\u0442\u043e\u043c \u0432 \u0427\u0435\u0440\u043d\u044b\u0445 \u0442\u043e\u043f\u044f\u0445 \u2014 \u0431\u043e\u043b\u043e\u0442\u0435, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u043f\u043e\u0437\u0436\u0435 \u0438\u0441\u0441\u043e\u0445\u043b\u043e \u0438 \u043f\u0440\u0435\u0432\u0440\u0430\u0442\u0438\u043b\u043e\u0441\u044c \u0432 \u0412\u044b\u0436\u0436\u0435\u043d\u043d\u044b\u0435 \u0437\u0435\u043c\u043b\u0438. \u041e\u0440\u043a\u0438 \u0445\u043b\u044b\u043d\u0443\u043b\u0438 \u0447\u0435\u0440\u0435\u0437 \u0442\u043e, \u0447\u0442\u043e \u0441\u0442\u0430\u043b\u043e \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e \u043a\u0430\u043a \u0422\u0435\u043c\u043d\u044b\u0439 \u043f\u043e\u0440\u0442\u0430\u043b, \u0438 \u0438\u0445 \u0440\u0430\u0437\u0432\u0435\u0434\u0447\u0438\u043a\u0438 \u0432\u0441\u043a\u043e\u0440\u0435 \u043d\u0430\u0448\u043b\u0438 \u0431\u043e\u0433\u0430\u0442\u044b\u0435 \u043f\u043e\u043b\u044f \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u0410\u0437\u0435\u0440\u043e\u0442, \u043d\u044b\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u0428\u0442\u043e\u0440\u043c\u0433\u0440\u0430\u0434\u0430.","\u041a\u043e\u0440\u043e\u043b\u044c \u041b\u043b\u0435\u0439\u043d \u0420\u0438\u043d\u043d \u0438 \u0435\u0433\u043e \u0437\u0430\u0449\u0438\u0442\u043d\u0438\u043a \u0410\u043d\u0434\u0443\u0438\u043d \u041b\u043e\u0442\u0430\u0440 \u0433\u043e\u0434\u0430\u043c\u0438 \u043e\u0442\u0431\u0438\u0432\u0430\u043b\u0438\u0441\u044c. \u0423\u0447\u0435\u043d\u0438\u043a \u0441\u0430\u043c\u043e\u0433\u043e \u041c\u0435\u0434\u0438\u0432\u0430, \u041a\u0430\u0434\u0433\u0430\u0440, \u0440\u0430\u0441\u043a\u0440\u044b\u043b \u043f\u0440\u0435\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0443\u0447\u0438\u0442\u0435\u043b\u044f \u0438 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u041b\u043e\u0442\u0430\u0440\u043e\u043c \u0438 \u043f\u043e\u043b\u0443\u043e\u0440\u043a\u043e\u0439 \u0413\u0430\u0440\u043e\u043d\u043e\u0439 \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u043b \u0425\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u044f \u0432 \u041a\u0430\u0440\u0430\u0436\u0430\u043d\u0435 \u0438 \u0443\u0431\u0438\u043b \u0435\u0433\u043e. \u041f\u043e\u0431\u0435\u0434\u0430 \u043f\u0440\u0438\u0448\u043b\u0430 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u043f\u043e\u0437\u0434\u043d\u043e. \u0411\u043e\u0435\u0432\u044b\u0435 \u043e\u0442\u0440\u044f\u0434\u044b \u041e\u0440\u0434\u044b \u0432\u044b\u0436\u0438\u0433\u0430\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043d\u0430 \u0441\u0432\u043e\u0435\u043c \u043f\u0443\u0442\u0438, \u0430 \u0432\u043d\u0443\u0442\u0440\u0438 \u041e\u0440\u0434\u044b \u0445\u0438\u0442\u0440\u044b\u0439 \u041e\u0440\u0433\u0440\u0438\u043c \u041c\u043e\u043b\u043e\u0442 \u0420\u043e\u043a\u0430 \u0441\u0432\u0435\u0440\u0433 \u0427\u0435\u0440\u043d\u043e\u0440\u0443\u043a\u0430 \u0438 \u0441\u0442\u0430\u043b \u0432\u043e\u0436\u0434\u0435\u043c.","\u0413\u0430\u0440\u043e\u043d\u0430, \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u0430\u044f \u0447\u0430\u0440\u0430\u043c\u0438 \u0413\u0443\u043b'\u0434\u0430\u043d\u0430, \u0443\u0431\u0438\u043b\u0430 \u043a\u043e\u0440\u043e\u043b\u044f \u041b\u043b\u0435\u0439\u043d\u0430, \u0438 \u0428\u0442\u043e\u0440\u043c\u0433\u0440\u0430\u0434 \u043f\u0430\u043b \u0438 \u0441\u0433\u043e\u0440\u0435\u043b. \u041b\u043e\u0442\u0430\u0440 \u0441\u043e\u0431\u0440\u0430\u043b \u0443\u0446\u0435\u043b\u0435\u0432\u0448\u0438\u0445, \u0441\u0440\u0435\u0434\u0438 \u043d\u0438\u0445 \u044e\u043d\u043e\u0433\u043e \u0441\u044b\u043d\u0430 \u041b\u043b\u0435\u0439\u043d\u0430 \u0412\u0430\u0440\u0438\u0430\u043d\u0430, \u0438 \u0443\u0432\u0435\u043b \u0438\u0445 \u0437\u0430 \u043c\u043e\u0440\u0435, \u0432 \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d. \u0414\u0430\u043b\u0435\u043a\u043e \u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a\u0435, \u0432 Riverglades \u2014 \u043a\u0440\u0430\u044e, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 Forever, \u2014 \u041e\u0440\u0434\u0430 \u0441\u0440\u043e\u0432\u043d\u044f\u043b\u0430 \u0441 \u0437\u0435\u043c\u043b\u0435\u0439 \u043f\u043e\u0441\u0435\u043b\u0435\u043d\u0438\u0435 Sunnyglade \u0438 \u0443\u0433\u043d\u0430\u043b\u0430 \u0432\u044b\u0436\u0438\u0432\u0448\u0438\u0445 \u0432 \u0440\u0430\u0431\u0441\u0442\u0432\u043e."]},"chapter:the-second-war":{title:"\u0412\u0442\u043e\u0440\u0430\u044f \u0432\u043e\u0439\u043d\u0430",summary:"\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u043b\u044e\u0434\u0435\u0439, \u044d\u043b\u044c\u0444\u044b, \u0434\u0432\u043e\u0440\u0444\u044b \u0438 \u0433\u043d\u043e\u043c\u044b \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0438\u043b\u0438\u0441\u044c \u0432 \u0410\u043b\u044c\u044f\u043d\u0441 \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d\u0430 \u0438 \u0440\u0430\u0437\u0431\u0438\u043b\u0438 \u041e\u0440\u0434\u0443 \u041c\u043e\u043b\u043e\u0442\u0430 \u0420\u043e\u043a\u0430 \u0443 \u041f\u0438\u043a\u0430 \u0427\u0435\u0440\u043d\u043e\u0439 \u0433\u043e\u0440\u044b.",when:"\u041f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0447\u0435\u0440\u0435\u0437 \u043f\u044f\u0442\u044c-\u0448\u0435\u0441\u0442\u044c \u043b\u0435\u0442 \u043f\u043e\u0441\u043b\u0435 \u0422\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0430\u043b\u0430",body:["\u041f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u0435 \u041b\u043e\u0442\u0430\u0440\u0430 \u043f\u043e\u0431\u0443\u0434\u0438\u043b\u043e \u043a\u043e\u0440\u043e\u043b\u044f \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d\u0430 \u0422\u0435\u0440\u0435\u043d\u0430\u0441\u0430 \u041c\u0435\u043d\u0435\u0442\u0438\u043b\u0430 \u0441\u043e\u0437\u0432\u0430\u0442\u044c \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u043b\u044e\u0434\u0435\u0439. \u041e\u043d\u0438 \u0441\u043e\u0437\u0434\u0430\u043b\u0438 \u0410\u043b\u044c\u044f\u043d\u0441 \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d\u0430 \u0432\u043e \u0433\u043b\u0430\u0432\u0435 \u0441 \u041b\u043e\u0442\u0430\u0440\u043e\u043c \u043a\u0430\u043a \u0432\u0435\u0440\u0445\u043e\u0432\u043d\u044b\u043c \u0433\u043b\u0430\u0432\u043d\u043e\u043a\u043e\u043c\u0430\u043d\u0434\u0443\u044e\u0449\u0438\u043c; \u043a \u043d\u0438\u043c \u043f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0438\u043b\u0438\u0441\u044c \u0434\u0432\u043e\u0440\u0444\u044b \u0421\u0442\u0430\u043b\u044c\u0433\u043e\u0440\u043d\u0430, \u0433\u043d\u043e\u043c\u044b \u0438, \u0432\u0435\u0440\u043d\u044b\u0435 \u0434\u0440\u0435\u0432\u043d\u0435\u0439 \u043a\u043b\u044f\u0442\u0432\u0435 \u0440\u043e\u0434\u0443 \u0410\u0440\u0430\u0442\u043e\u0440\u0430, \u0432\u044b\u0441\u0448\u0438\u0435 \u044d\u043b\u044c\u0444\u044b \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441\u0430. \u0427\u0442\u043e\u0431\u044b \u0432\u0441\u0435\u043b\u0438\u0442\u044c \u0432 \u0441\u043e\u043b\u0434\u0430\u0442 \u043d\u0430\u0434\u0435\u0436\u0434\u0443, \u0430\u0440\u0445\u0438\u0435\u043f\u0438\u0441\u043a\u043e\u043f \u0410\u043b\u043e\u043d\u0441\u0438\u0439 \u0424\u0430\u043e\u043b \u043e\u0441\u043d\u043e\u0432\u0430\u043b \u043e\u0440\u0434\u0435\u043d \u0420\u044b\u0446\u0430\u0440\u0435\u0439 \u0421\u0435\u0440\u0435\u0431\u0440\u044f\u043d\u043e\u0439 \u0414\u043b\u0430\u043d\u0438, \u043f\u0435\u0440\u0432\u044b\u0445 \u043f\u0430\u043b\u0430\u0434\u0438\u043d\u043e\u0432, \u0432\u043e \u0433\u043b\u0430\u0432\u0435 \u0441 \u0423\u0442\u0435\u0440\u043e\u043c \u0421\u0432\u0435\u0442\u043e\u043d\u043e\u0441\u043d\u044b\u043c.","\u041e\u0440\u0434\u0430 \u041c\u043e\u043b\u043e\u0442\u0430 \u0420\u043e\u043a\u0430 \u0442\u043e\u0436\u0435 \u0432\u044b\u0440\u043e\u0441\u043b\u0430. \u041e\u0433\u0440\u044b, \u0442\u0440\u043e\u043b\u043b\u0438 \u0410\u043c\u0430\u043d\u0438 \u043f\u043e\u0434 \u043d\u0430\u0447\u0430\u043b\u043e\u043c \u0417\u0443\u043b'\u0434\u0436\u0438\u043d\u0430 \u0438 \u0433\u043e\u0431\u043b\u0438\u043d\u044b-\u0441\u0430\u043f\u0435\u0440\u044b \u0441\u0440\u0430\u0436\u0430\u043b\u0438\u0441\u044c \u0431\u043e\u043a \u043e \u0431\u043e\u043a \u0441 \u043e\u0440\u043a\u0430\u043c\u0438; \u043a\u043b\u0430\u043d \u0414\u0440\u0430\u043a\u043e\u043d\u044c\u0435\u0439 \u041f\u0430\u0441\u0442\u0438 \u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e \u0414\u0443\u0448\u0438 \u0414\u0440\u0430\u043a\u043e\u043d\u0430 \u0421\u043c\u0435\u0440\u0442\u043e\u043a\u0440\u044b\u043b\u0430 \u043f\u043e\u0440\u0430\u0431\u043e\u0442\u0438\u043b \u043a\u0440\u0430\u0441\u043d\u044b\u0445 \u0434\u0440\u0430\u043a\u043e\u043d\u043e\u0432 \u0432 \u0413\u0440\u0438\u043c \u0411\u0430\u0442\u043e\u043b\u0435; \u0413\u0443\u043b'\u0434\u0430\u043d \u0441\u043e\u0437\u0434\u0430\u043b \u043f\u0435\u0440\u0432\u044b\u0445 \u0440\u044b\u0446\u0430\u0440\u0435\u0439 \u0441\u043c\u0435\u0440\u0442\u0438. \u041e\u0440\u0434\u0430 \u0437\u0430\u0445\u0432\u0430\u0442\u0438\u043b\u0430 \u041a\u0430\u0437 \u041c\u043e\u0434\u0430\u043d, \u0441\u043e\u0436\u0433\u043b\u0430 \u0447\u0430\u0441\u0442\u044c \u041a\u0435\u043b\u044c'\u0422\u0430\u043b\u0430\u0441\u0430 \u0438 \u043e\u0441\u0430\u0434\u0438\u043b\u0430 \u0441\u0442\u043e\u043b\u0438\u0446\u0443 \u041b\u043e\u0440\u0434\u0435\u0440\u043e\u043d\u0430.","\u0412 \u0440\u0435\u0448\u0430\u044e\u0449\u0438\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 \u0413\u0443\u043b'\u0434\u0430\u043d \u043f\u0440\u0435\u0434\u0430\u043b \u041c\u043e\u043b\u043e\u0442\u0430 \u0420\u043e\u043a\u0430 \u0438 \u0443\u043f\u043b\u044b\u043b, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u0434\u043d\u044f\u0442\u044c \u0441\u043e \u0434\u043d\u0430 \u0413\u0440\u043e\u0431\u043d\u0438\u0446\u0443 \u0421\u0430\u0440\u0433\u0435\u0440\u0430\u0441\u0430, \u0437\u0430\u0431\u0440\u0430\u0432 \u0441 \u0441\u043e\u0431\u043e\u0439 \u0434\u0432\u0430 \u043a\u043b\u0430\u043d\u0430, Stormreaver \u0438 \u0421\u0443\u043c\u0435\u0440\u0435\u0447\u043d\u044b\u0439 \u041c\u043e\u043b\u043e\u0442. \u041e\u0441\u043b\u0430\u0431\u043b\u0435\u043d\u043d\u0430\u044f \u041e\u0440\u0434\u0430 \u043e\u0442\u0441\u0442\u0443\u043f\u0438\u043b\u0430 \u043a \u0427\u0435\u0440\u043d\u043e\u0439 \u0433\u043e\u0440\u0435. \u0412 \u0431\u0438\u0442\u0432\u0435 \u0443 \u041f\u0438\u043a\u0430 \u0427\u0435\u0440\u043d\u043e\u0439 \u0433\u043e\u0440\u044b \u041c\u043e\u043b\u043e\u0442 \u0420\u043e\u043a\u0430 \u0443\u0431\u0438\u043b \u041b\u043e\u0442\u0430\u0440\u0430, \u043d\u043e \u0435\u0433\u043e \u0437\u0430\u043c\u0435\u0441\u0442\u0438\u0442\u0435\u043b\u044c \u0422\u0443\u0440\u0430\u043b\u0438\u043e\u043d \u0440\u0430\u0437\u0433\u0440\u043e\u043c\u0438\u043b \u041e\u0440\u0434\u0443, \u0430 \u041a\u0430\u0434\u0433\u0430\u0440 \u0443\u043d\u0438\u0447\u0442\u043e\u0436\u0438\u043b \u0422\u0435\u043c\u043d\u044b\u0439 \u043f\u043e\u0440\u0442\u0430\u043b. \u0412\u044b\u0436\u0438\u0432\u0448\u0438\u0445 \u043e\u0440\u043a\u043e\u0432 \u0441\u043e\u0433\u043d\u0430\u043b\u0438 \u0432 \u043b\u0430\u0433\u0435\u0440\u044f \u0434\u043b\u044f \u0438\u043d\u0442\u0435\u0440\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445. \u0412 Riverglades \u0438\u0437 Forever \u043d\u043e\u0432\u044b\u0439 \u0434\u043e\u043c \u043d\u0430\u0448\u043b\u0438 \u043e\u0433\u0440\u044b \u0421\u0443\u043c\u0435\u0440\u0435\u0447\u043d\u043e\u0433\u043e \u041c\u043e\u043b\u043e\u0442\u0430 \u0438 \u043e\u0440\u043a\u0438 Stormreaver, \u0431\u0435\u0436\u0430\u0432\u0448\u0438\u0435 \u043e\u0442 \u0413\u0440\u043e\u0431\u043d\u0438\u0446\u044b."]}}},1771,[]);
